_FILES['audit/chain.py'] = '"""\nregintel_engine.audit.chain\n=============================\nHMAC-SHA256 tamper-evident audit chain.\n\n21 CFR Part 11 compliance properties:\n  - Every record sealed with HMAC-SHA256\n  - Each record includes hash of previous record (chain link)\n  - Any modification to any record breaks all subsequent signatures\n  - Full provenance: document → facts → rules → verdict\n  - Extracted_text included for every fact (enables independent verification)\n  - Regulatory citations included for every rule result\n  - SME approval record included for all ILP rules\n\nThe audit record is formatted in regulatory language.\nEvery regulator can read it and verify independently.\n"""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport hmac\nimport json\nimport logging\nimport os\nfrom datetime import datetime\nfrom typing import Any, Dict, List, Optional\n\nfrom ..models import AuditRecord, RuleResult, Verdict\n\nlog = logging.getLogger("regintel.audit")\n\n\nclass HMACauditChain:\n    """\n    Tamper-evident HMAC-SHA256 audit chain.\n\n    Each record:\n      1. Built from verdict + facts + rule_results\n      2. Previous record hash included\n      3. HMAC-SHA256 signature computed\n      4. Appended to in-memory chain and optionally saved to disk\n\n    Usage\n    -----\n        chain = HMACauditChain(key_env="REGINTEL_AUDIT_KEY")\n        record = chain.seal(verdict)\n        chain.save("audit_log.jsonl")\n\n        # Verify integrity\n        ok, issues = chain.verify()\n    """\n\n    SYSTEM_VERSION = "regintel-1.0.0"\n\n    def __init__(\n        self,\n        key_env:  str         = "REGINTEL_AUDIT_KEY",\n        key_hex:  Optional[str] = None,\n    ) -> None:\n        """\n        Parameters\n        ----------\n        key_env   Environment variable containing the HMAC key (hex)\n        key_hex   Direct key override (for testing only)\n        """\n        if key_hex:\n            self._key = bytes.fromhex(key_hex)\n        else:\n            raw = os.environ.get(key_env, "")\n            if not raw:\n                # Generate deterministic key from env name for development\n                raw = hashlib.sha256(key_env.encode()).hexdigest()\n                log.warning(f"[Audit] {key_env} not set — using derived key. "\n                            f"Set the environment variable for production.")\n            try:\n                self._key = bytes.fromhex(raw)\n            except ValueError:\n                self._key = hashlib.sha256(raw.encode()).digest()\n\n        self._records: List[AuditRecord] = []\n        self._prev_hash: str = "0" * 64   # genesis block\n\n    def seal(self, verdict: Verdict) -> AuditRecord:\n        """\n        Seal a verdict into a tamper-evident audit record.\n        Returns the signed AuditRecord.\n        """\n        # Serialise facts (with provenance)\n        extracted_facts = self._serialise_facts(verdict.facts)\n\n        # Serialise rule results (with citations)\n        rule_results = self._serialise_rules(verdict.rule_results)\n\n        # Compute hashes\n        doc_hash   = verdict.doc_hash\n        facts_hash = hashlib.sha256(\n            json.dumps(verdict.facts.facts, sort_keys=True, default=str).encode()\n        ).hexdigest()\n\n        record_id  = (f"REC-{datetime.utcnow().strftime(\'%Y%m%d%H%M%S\')}"\n                      f"-{doc_hash[:8]}")\n\n        # Build record payload (without signature)\n        payload = {\n            "record_id":       record_id,\n            "doc_hash":        doc_hash,\n            "facts_hash":      facts_hash,\n            "verdict":         verdict.verdict,\n            "domain":          verdict.domain,\n            "timestamp":       verdict.timestamp,\n            "system_version":  self.SYSTEM_VERSION,\n            "extracted_facts": extracted_facts,\n            "rule_results":    rule_results,\n            "prev_hash":       self._prev_hash,\n        }\n\n        # Compute record hash\n        payload_json = json.dumps(payload, sort_keys=True, default=str)\n        record_hash  = hashlib.sha256(payload_json.encode()).hexdigest()\n\n        # Compute HMAC signature\n        signature = hmac.new(\n            self._key,\n            payload_json.encode(),\n            hashlib.sha256,\n        ).hexdigest()\n\n        record = AuditRecord(\n            record_id       = record_id,\n            doc_hash        = doc_hash,\n            facts_hash      = facts_hash,\n            verdict         = verdict.verdict,\n            domain          = verdict.domain,\n            timestamp       = verdict.timestamp,\n            system_version  = self.SYSTEM_VERSION,\n            extracted_facts = extracted_facts,\n            rule_results    = rule_results,\n            prev_hash       = self._prev_hash,\n            record_hash     = record_hash,\n            signature       = signature,\n        )\n\n        self._prev_hash = record_hash\n        self._records.append(record)\n\n        log.debug(f"[Audit] sealed {record_id}: {verdict.verdict}")\n        return record\n\n    def verify(self) -> tuple:\n        """\n        Verify integrity of the entire audit chain.\n        Returns (all_ok: bool, issues: List[str]).\n        """\n        issues   = []\n        prev_hash = "0" * 64\n\n        for record in self._records:\n            # Rebuild payload without signature\n            payload = {\n                "record_id":       record.record_id,\n                "doc_hash":        record.doc_hash,\n                "facts_hash":      record.facts_hash,\n                "verdict":         record.verdict,\n                "domain":          record.domain,\n                "timestamp":       record.timestamp,\n                "system_version":  record.system_version,\n                "extracted_facts": record.extracted_facts,\n                "rule_results":    record.rule_results,\n                "prev_hash":       record.prev_hash,\n            }\n            payload_json = json.dumps(payload, sort_keys=True, default=str)\n\n            # Check chain link\n            if record.prev_hash != prev_hash:\n                issues.append(f"{record.record_id}: chain link broken")\n\n            # Check record hash\n            expected_hash = hashlib.sha256(payload_json.encode()).hexdigest()\n            if record.record_hash != expected_hash:\n                issues.append(f"{record.record_id}: record hash mismatch — tampered")\n\n            # Check HMAC signature\n            expected_sig = hmac.new(\n                self._key,\n                payload_json.encode(),\n                hashlib.sha256,\n            ).hexdigest()\n            if record.signature != expected_sig:\n                issues.append(f"{record.record_id}: HMAC signature invalid — tampered")\n\n            prev_hash = record.record_hash\n\n        all_ok = len(issues) == 0\n        return all_ok, issues\n\n    def save(self, path: str) -> None:\n        """Save audit chain to JSONL file."""\n        with open(path, "w") as f:\n            for record in self._records:\n                f.write(json.dumps(record.to_dict(), default=str) + "\\n")\n        log.info(f"[Audit] saved {len(self._records)} records → {path}")\n\n    @classmethod\n    def load(cls, path: str, key_env: str = "REGINTEL_AUDIT_KEY") -> "HMACauditChain":\n        """Load audit chain from JSONL file."""\n        chain = cls(key_env=key_env)\n        chain._records = []\n\n        with open(path) as f:\n            for line in f:\n                data = json.loads(line.strip())\n                record = AuditRecord(**data)\n                chain._records.append(record)\n                chain._prev_hash = record.record_hash\n\n        log.info(f"[Audit] loaded {len(chain._records)} records from {path}")\n        return chain\n\n    def format_record(self, record: AuditRecord) -> str:\n        """Format a record in human-readable regulatory language."""\n        lines = [\n            "═" * 70,\n            "REGULATORY COMPLIANCE ASSESSMENT RECORD",\n            f"System: RegIntel {record.system_version}",\n            "═" * 70,\n            f"Record ID:   {record.record_id}",\n            f"Document:    {record.doc_hash[:16]}...",\n            f"Domain:      {record.domain}",\n            f"Date:        {record.timestamp[:19]} UTC",\n            f"Verdict:     {record.verdict}",\n            "",\n        ]\n\n        # Failed rules\n        failed = [r for r in record.rule_results if r.get("passed") is False]\n        if failed:\n            lines.append("FINDINGS:")\n            for result in failed:\n                lines.extend([\n                    f"  {\'─\'*60}",\n                    f"  Rule:        {result[\'rule_id\']} ({result[\'severity\'].upper()})",\n                    f"  Finding:     {result[\'message\']}",\n                    f"  Regulation:  {result[\'regulation\']}",\n                    f"  Source:      {result[\'rule_source\']}",\n                ])\n                if result.get("evidence"):\n                    for pred, ev in result["evidence"].items():\n                        if ev.get("value") is not None:\n                            lines.append(\n                                f"  Evidence:    {pred} = {ev[\'value\']}"\n                                f"  ← \\"{ev.get(\'extracted_text\', \'\')[:80]}\\""\n                            )\n            lines.append("")\n\n        # Audit integrity\n        lines.extend([\n            "AUDIT INTEGRITY:",\n            f"  Document hash:  {record.doc_hash[:32]}...",\n            f"  Record hash:    {record.record_hash[:32]}...",\n            f"  HMAC signature: {record.signature[:32]}...",\n            f"  Chain link:     {record.prev_hash[:16]}...",\n            "═" * 70,\n        ])\n\n        return "\\n".join(lines)\n\n    # ── Serialisation helpers ─────────────────────────────────────────────────\n\n    @staticmethod\n    def _serialise_facts(facts) -> List[Dict]:\n        """Serialise FactDict with full provenance."""\n        result = []\n        for name, value in facts.facts.items():\n            prov = facts.provenance.get(name)\n            result.append({\n                "name":           name,\n                "value":          value,\n                "extracted_text": prov.extracted_text if prov else "",\n                "confidence":     prov.confidence    if prov else 0.0,\n                "reasoning":      prov.reasoning     if prov else "",\n                "source_type":    prov.source_type   if prov else "structured",\n            })\n        for name in facts.absent_facts:\n            result.append({\n                "name":           name,\n                "value":          None,\n                "extracted_text": "",\n                "confidence":     0.0,\n                "reasoning":      "absent or low confidence",\n                "source_type":    "absent",\n            })\n        return result\n\n    @staticmethod\n    def _serialise_rules(rule_results: List[RuleResult]) -> List[Dict]:\n        """Serialise RuleResults with citations."""\n        result = []\n        for rr in rule_results:\n            result.append({\n                "rule_id":         rr.rule_id,\n                "rule_name":       rr.rule_name,\n                "domain":          rr.domain,\n                "severity":        rr.severity,\n                "passed":          rr.passed,\n                "message":         rr.message,\n                "regulation":      rr.regulation,\n                "regulation_text": rr.regulation_text,\n                "regulation_url":  rr.regulation_url,\n                "evidence":        rr.evidence,\n                "rule_source":     rr.rule_source,\n                "confidence":      rr.confidence,\n                "approved_by":     rr.approved_by,\n                "approved_on":     rr.approved_on,\n            })\n        return result\n'

_FILES['extraction/__init__.py'] = '"""regintel_engine.extraction"""'

_FILES['extraction/llm_extractor.py'] = '"""\nregintel_engine.extraction.llm_extractor\n=========================================\nLLM-based fact extraction from regulatory documents.\n\nThis is the ONLY neural component that runs at test time.\nIt is justified because:\n  - Regulatory documents are unstructured text\n  - No other technology reads scanned PDFs or complex DOCX reliably\n  - LLM understands regulatory language (trained on all of it)\n\nThe LLM is a PARSER only. It never makes compliance decisions.\nEvery output is a discrete fact that will be checked by the symbolic engine.\n\nTwo modes\n---------\nONLINE mode:  Uses Qwen2.5-1.5B (or any HuggingFace model) locally.\n              Temperature 0.1 for deterministic structured output.\n\nMOCK mode:    Returns deterministic test facts without a model.\n              Used for unit tests and when no GPU is available.\n\nOutput contract\n---------------\nEvery returned ExtractedFact must have:\n  - extracted_text: exact sentence from document (enables hallucination check)\n  - confidence:     0.0-1.0 extraction confidence\n  - reasoning:      one sentence why this was extracted\n\nFacts are in document language — normalizer converts to standard vocabulary.\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport logging\nimport re\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom ..models import ExtractedFact\n\nlog = logging.getLogger("regintel.extractor")\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  EXTRACTION PROMPTS\n# ─────────────────────────────────────────────────────────────────────────────\n\nSTRUCTURED_EXTRACTION_PROMPT = """You are a regulatory compliance fact extractor.\nRead this document and extract every compliance-relevant structured fact.\n\nRULES:\n1. Only extract facts EXPLICITLY stated in the document\n2. For each fact provide the EXACT sentence you extracted it from\n3. Return null if the information is not present — never assume or infer\n4. Copy numerical values EXACTLY as written\n5. For pass/fail: only use explicit PASS/FAIL/COMPLIANT/NON-COMPLIANT text\n\nDocument (domain: {domain}):\n{document}\n\nExtract the following structured facts. Return ONLY valid JSON, no explanation.\n\n{{\n  "device_class": {{"value": "I"|"II"|"III"|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "calibration_current": {{"value": true|false|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "api_coa_reviewed": {{"value": true|false|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "process_in_spec": {{"value": true|false|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "clinical_n": {{"value": integer|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "p_value": {{"value": float|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "adverse_events_count": {{"value": integer|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "has_results": {{"value": true|false|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "predicate_device": {{"value": "K-number string"|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "risk_management_standard": {{"value": "ISO 14971"|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "qms_standard": {{"value": "21 CFR 820"|"ISO 13485"|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "software_class": {{"value": "A"|"B"|"C"|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "dissolution_pass": {{"value": true|false|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "sterility_tested": {{"value": true|false|null, "extracted_text": "...", "confidence": 0.0-1.0}},\n  "recall_classification": {{"value": "Class I"|"Class II"|"Class III"|null, "extracted_text": "...", "confidence": 0.0-1.0}}\n}}"""\n\nTEXT_CLASSIFICATION_PROMPT = """You are a senior regulatory compliance analyst.\n\nRead this text from a regulatory document and classify it against the controlled predicate vocabulary.\n\nREASONING RULES:\n1. NEGATION: "no deviations recorded" → deviation_occurred: false (not true)\n2. SEVERITY: "minor variation within tolerance" → process_oos: false\n3. TEMPORAL: "was overdue but has since been renewed" → check CURRENT state only\n4. IMPLICATION: "batch quarantined" implies investigation_open: true\n5. DOMAIN KNOWLEDGE: N=15 for Class I = adequate; N=15 for Class III = inadequate\n6. Do NOT classify based on keyword presence alone — understand logical meaning\n\nDocument context:\n  Domain:       {domain}\n  Device class: {device_class_if_known}\n  Other facts:  {other_facts}\n\nText to classify:\n{text}\n\nThis text describes field: {field_name}\n\nControlled vocabulary for domain {domain}:\n{vocabulary}\n\nFor each predicate that applies to this text, return:\n[\n  {{\n    "predicate":      "predicate_name_from_vocabulary",\n    "value":          true or false,\n    "confidence":     0.0-1.0,\n    "evidence":       "exact phrase from text",\n    "reasoning":      "one sentence explaining logical inference",\n    "qualifications": "any conditions or null"\n  }}\n]\n\nReturn ONLY predicates supported by the text. Return [] if none apply.\nReturn ONLY valid JSON."""\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  LLM FACT EXTRACTOR\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass LLMFactExtractor:\n    """\n    Extracts facts from regulatory documents using a local LLM.\n\n    The LLM runs locally (never calls external APIs).\n    Document text never leaves the deployment environment.\n\n    Usage\n    -----\n        extractor = LLMFactExtractor.from_model("Qwen/Qwen2.5-1.5B-Instruct")\n        facts     = extractor.extract_structured(document, domain="gmp")\n        text_pred = extractor.classify_text(text, field, vocab, domain, context)\n    """\n\n    def __init__(self, model=None, tokenizer=None) -> None:\n        self._model     = model\n        self._tokenizer = tokenizer\n        self._mock_mode = (model is None)\n\n    @classmethod\n    def from_model(cls, model_name: str = "Qwen/Qwen2.5-1.5B-Instruct") -> "LLMFactExtractor":\n        """Load model from HuggingFace. Requires transformers and torch."""\n        try:\n            from transformers import AutoModelForCausalLM, AutoTokenizer\n            import torch\n\n            log.info(f"Loading LLM: {model_name}")\n            tokenizer = AutoTokenizer.from_pretrained(model_name)\n            model     = AutoModelForCausalLM.from_pretrained(\n                model_name,\n                torch_dtype = torch.float16,\n                device_map  = "auto",\n            )\n            model.eval()\n            log.info("LLM loaded successfully")\n            return cls(model=model, tokenizer=tokenizer)\n\n        except ImportError as e:\n            log.warning(f"transformers/torch not available: {e}. "\n                        f"Using mock mode.")\n            return cls(model=None, tokenizer=None)\n\n    @classmethod\n    def mock(cls) -> "LLMFactExtractor":\n        """Mock extractor for testing without a model."""\n        return cls(model=None, tokenizer=None)\n\n    # ── Core generation ───────────────────────────────────────────────────────\n\n    def _generate(self, prompt: str, max_new_tokens: int = 512) -> str:\n        """\n        Generate text from the LLM with low temperature for determinism.\n        Falls back to mock output if model not available.\n        """\n        if self._mock_mode:\n            return self._mock_generate(prompt)\n\n        import torch\n\n        inputs = self._tokenizer(\n            prompt,\n            return_tensors  = "pt",\n            max_length      = 3000,\n            truncation      = True,\n        ).to(self._model.device)\n\n        with torch.no_grad():\n            output_ids = self._model.generate(\n                inputs["input_ids"],\n                max_new_tokens  = max_new_tokens,\n                temperature     = 0.1,\n                do_sample       = False,  # greedy for determinism\n                pad_token_id    = self._tokenizer.eos_token_id,\n            )\n\n        new_tokens = output_ids[0][inputs["input_ids"].shape[1]:]\n        return self._tokenizer.decode(new_tokens, skip_special_tokens=True)\n\n    def _parse_json(self, text: str) -> Any:\n        """Extract and parse JSON from LLM output."""\n        # Strip markdown fences\n        text = re.sub(r"```(?:json)?", "", text).strip()\n\n        # Try direct parse\n        try:\n            return json.loads(text)\n        except json.JSONDecodeError:\n            pass\n\n        # Try to find JSON object/array in output\n        for pattern in [r"\\{.*\\}", r"\\[.*\\]"]:\n            match = re.search(pattern, text, re.DOTALL)\n            if match:\n                try:\n                    return json.loads(match.group())\n                except json.JSONDecodeError:\n                    pass\n\n        log.debug(f"JSON parse failed on: {text[:200]}")\n        return None\n\n    # ── Structured fact extraction ────────────────────────────────────────────\n\n    def extract_structured(\n        self,\n        document: str,\n        domain:   str = "gmp",\n    ) -> List[ExtractedFact]:\n        """\n        Extract structured facts (boolean, numeric, ordered string) from document.\n        Returns list of ExtractedFact with extracted_text for each.\n        """\n        prompt = STRUCTURED_EXTRACTION_PROMPT.format(\n            domain   = domain,\n            document = document[:4000],\n        )\n        raw = self._generate(prompt)\n        return self._parse_structured_output(raw, document)\n\n    def _parse_structured_output(\n        self,\n        raw:      str,\n        document: str,\n    ) -> List[ExtractedFact]:\n        parsed = self._parse_json(raw)\n        if not isinstance(parsed, dict):\n            log.warning("Structured extraction returned non-dict")\n            return []\n\n        facts = []\n        for field_name, field_data in parsed.items():\n            if not isinstance(field_data, dict):\n                continue\n\n            value          = field_data.get("value")\n            extracted_text = field_data.get("extracted_text", "")\n            confidence     = float(field_data.get("confidence", 0.5))\n\n            if value is None:\n                continue   # absent — skip entirely\n\n            facts.append(ExtractedFact(\n                name           = field_name,\n                value          = value,\n                extracted_text = extracted_text,\n                confidence     = confidence,\n                source_type    = "structured",\n            ))\n\n        return facts\n\n    # ── Text predicate classification ─────────────────────────────────────────\n\n    def classify_text(\n        self,\n        text:         str,\n        field_name:   str,\n        vocabulary:   str,\n        domain:       str,\n        device_class: str = "unknown",\n        other_facts:  str = "none",\n    ) -> List[ExtractedFact]:\n        """\n        Intelligently classify a text description against the controlled vocabulary.\n        Handles negation, severity, temporal context, and domain knowledge.\n        """\n        if not text or len(text.strip()) < 10:\n            return []\n\n        prompt = TEXT_CLASSIFICATION_PROMPT.format(\n            domain             = domain,\n            device_class_if_known = device_class,\n            other_facts        = other_facts,\n            text               = text[:1500],\n            field_name         = field_name,\n            vocabulary         = vocabulary,\n        )\n        raw  = self._generate(prompt, max_new_tokens=400)\n        return self._parse_classification_output(raw)\n\n    def _parse_classification_output(self, raw: str) -> List[ExtractedFact]:\n        parsed = self._parse_json(raw)\n        if not isinstance(parsed, list):\n            return []\n\n        facts = []\n        for item in parsed:\n            if not isinstance(item, dict):\n                continue\n\n            predicate   = item.get("predicate", "")\n            value       = item.get("value")\n            confidence  = float(item.get("confidence", 0.5))\n            evidence    = item.get("evidence", "")\n            reasoning   = item.get("reasoning", "")\n\n            if not predicate or value is None:\n                continue\n\n            facts.append(ExtractedFact(\n                name           = predicate,\n                value          = bool(value),\n                extracted_text = evidence,\n                confidence     = confidence,\n                reasoning      = reasoning,\n                source_type    = "text_predicate",\n            ))\n\n        return facts\n\n    # ── Mock mode ─────────────────────────────────────────────────────────────\n\n    def _mock_generate(self, prompt: str) -> str:\n        """\n        Deterministic mock for all 4 regulatory domains.\n        Reads signals from the document text embedded in the prompt.\n\n        Covers: GMP, FDA Device, Clinical Trials, SEC Financial.\n        Used for testing and Kaggle runs without GPU.\n        """\n        p = prompt.lower()\n\n        # ── Structured extraction ──────────────────────────────────────\n        if "device_class" in prompt and "dissolution_pass" in prompt:\n            result: Dict[str, Any] = {}\n\n            # ── GMP signals ───────────────────────────────────────────\n            if any(kw in p for kw in ["calibration expired", "calibration overdue",\n                                       "overdue since", "past due calibration"]):\n                result["calibration_current"] = {\n                    "value": False,\n                    "extracted_text": "calibration expired",\n                    "confidence": 0.92,\n                }\n            elif any(kw in p for kw in ["calibration current", "calibration valid",\n                                         "calibration verified"]):\n                result["calibration_current"] = {\n                    "value": True,\n                    "extracted_text": "calibration current",\n                    "confidence": 0.92,\n                }\n\n            if any(kw in p for kw in ["coa not received", "coa not on file",\n                                       "certificate of analysis not",\n                                       "no coa", "coa absent"]):\n                result["api_coa_reviewed"] = {\n                    "value": False,\n                    "extracted_text": "CoA not received",\n                    "confidence": 0.93,\n                }\n            elif any(kw in p for kw in ["coa reviewed", "coa approved",\n                                         "certificate of analysis reviewed",\n                                         "coa on file"]):\n                result["api_coa_reviewed"] = {\n                    "value": True,\n                    "extracted_text": "CoA reviewed and approved",\n                    "confidence": 0.93,\n                }\n\n            if any(kw in p for kw in ["dissolution", "failed specification",\n                                       "out of specification", "oos"]):\n                result["dissolution_pass"] = {\n                    "value": False,\n                    "extracted_text": "dissolution failed specification",\n                    "confidence": 0.90,\n                }\n            elif any(kw in p for kw in ["dissolution passed", "within spec",\n                                         "meets specification"]):\n                result["dissolution_pass"] = {\n                    "value": True,\n                    "extracted_text": "dissolution passed",\n                    "confidence": 0.90,\n                }\n\n            if any(kw in p for kw in ["sterility test failure", "sterility failure",\n                                       "non-sterile", "sterility testing failure"]):\n                result["sterility_tested"] = {\n                    "value": False,\n                    "extracted_text": "sterility testing failure",\n                    "confidence": 0.93,\n                }\n            elif any(kw in p for kw in ["sterility confirmed", "sterility passed",\n                                         "sterile product"]):\n                result["sterility_tested"] = {\n                    "value": True,\n                    "extracted_text": "sterility confirmed",\n                    "confidence": 0.90,\n                }\n\n            # ── FDA Device signals ────────────────────────────────────\n            # Search specifically for "Device Class: Class X" or "Class X recall"\n            # to avoid matching "Class I|Class II|Class III" in the prompt schema\n            import re as _re\n            cls_match = _re.search(\n                r\'(?:device class|class)\\s*:?\\s*class\\s+(i{1,3}|ii|iii)\',\n                p, _re.IGNORECASE)\n            if cls_match:\n                cls_raw = cls_match.group(1).upper()\n                cls_val = {"I": "I", "II": "II", "III": "III",\n                           "IIII": "III"}.get(cls_raw, cls_raw)\n                result["device_class"] = {\n                    "value": cls_val,\n                    "extracted_text": f"Device Class: Class {cls_val}",\n                    "confidence": 0.95,\n                }\n\n            k_match = _re.search(r"predicate\\s+device\\s+(k\\d{6})", p, _re.IGNORECASE)\n            if not k_match:\n                k_match = _re.search(r"k-number[:\\s]+(k\\d{6})", p, _re.IGNORECASE)\n            if not k_match:\n                k_match = _re.search(r"\\bk(\\d{6})\\b", p, _re.IGNORECASE)\n            if k_match:\n                k_num = k_match.group(1) if k_match.lastindex == 1 else k_match.group(0)\n                k_num = k_num.upper() if k_num.upper().startswith(\'K\') else f"K{k_num}"\n                result["predicate_device"] = {\n                    "value": k_num,\n                    "extracted_text": f"predicate device {k_num}",\n                    "confidence": 0.97,\n                }\n\n            if "iso 14971" in p or "risk management" in p and "documented" in p:\n                result["risk_management_standard"] = {\n                    "value": "ISO 14971",\n                    "extracted_text": "risk management per ISO 14971",\n                    "confidence": 0.91,\n                }\n\n            if "software" in p and any(kw in p for kw in\n                                        ["deficiency", "error", "defect", "failure"]):\n                result["software_class"] = {\n                    "value": "C",\n                    "extracted_text": "software deficiency",\n                    "confidence": 0.85,\n                }\n\n            # ── Clinical signals ──────────────────────────────────────\n            n_match = re.search(r"(?:n\\s*=\\s*|enrolled\\s+)(\\d+)", p)\n            if n_match:\n                result["clinical_n"] = {\n                    "value": int(n_match.group(1)),\n                    "extracted_text": f"N={n_match.group(1)} subjects",\n                    "confidence": 0.96,\n                }\n\n            p_match = re.search(r"p\\s*[<>=]\\s*(0\\.\\d+)", p)\n            if p_match:\n                result["p_value"] = {\n                    "value": float(p_match.group(1)),\n                    "extracted_text": f"p={p_match.group(1)}",\n                    "confidence": 0.95,\n                }\n\n            if any(kw in p for kw in ["results posted", "results first post",\n                                       "results submitted to clinicaltrials"]):\n                result["has_results"] = {\n                    "value": True,\n                    "extracted_text": "results posted",\n                    "confidence": 0.95,\n                }\n            elif any(kw in p for kw in ["results not posted", "no results",\n                                         "results: no", "has results: no",\n                                         "results posted: no"]):\n                result["has_results"] = {\n                    "value": False,\n                    "extracted_text": "results not posted",\n                    "confidence": 0.95,\n                }\n\n            # ── Recall classification ─────────────────────────────────\n            for cls_str, cls_val in [("class i recall",   "Class I"),\n                                      ("class ii recall",  "Class II"),\n                                      ("class iii recall", "Class III")]:\n                if cls_str in p:\n                    result["recall_classification"] = {\n                        "value": cls_val,\n                        "extracted_text": cls_val,\n                        "confidence": 0.97,\n                    }\n                    break\n\n            return json.dumps(result)\n\n        # ── Text predicate classification ──────────────────────────────\n        if "predicate" in prompt and "vocabulary" in prompt:\n            # CRITICAL: only analyse the actual document text, not the full\n            # prompt (which includes vocabulary descriptions containing the\n            # very keywords we are searching for).\n            # TEXT_CLASSIFICATION_PROMPT places document text after marker.\n            import re as _re\n            doc_section = prompt\n            for marker in ["Text to classify:\\n", "text to classify:\\n",\n                           "TEXT TO CLASSIFY:\\n"]:\n                idx = prompt.find(marker)\n                if idx != -1:\n                    # Only the text after the marker; stop at "Controlled vocabulary"\n                    after = prompt[idx + len(marker):]\n                    end   = after.find("\\nThis text describes field:")\n                    doc_section = after[:end] if end != -1 else after[:1500]\n                    break\n\n            tl = doc_section.lower()\n            results: list = []\n\n            # ── GMP text predicates ───────────────────────────────────\n            if any(kw in tl for kw in ["coa not", "certificate of analysis not",\n                                        "no coa", "coa absent", "coa missing"]):\n                results.append({\n                    "predicate": "api_coa_missing", "value": True,\n                    "confidence": 0.91,\n                    "evidence": "CoA not received prior to use",\n                    "reasoning": "Document states CoA was not received",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["calibration overdue", "calibration expired",\n                                         "past due calibration",\n                                         "calibration lapsed"]):\n                results.append({\n                    "predicate": "calibration_expired", "value": True,\n                    "confidence": 0.93,\n                    "evidence": "calibration overdue",\n                    "reasoning": "Calibration described as overdue or expired",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["deviation", "discrepancy",\n                                         "out-of-specification event"]):\n                if any(kw in tl for kw in ["no corrective", "no capa",\n                                             "without investigation",\n                                             "no investigation"]):\n                    results.append({\n                        "predicate": "deviation_without_capa", "value": True,\n                        "confidence": 0.89,\n                        "evidence": "deviation without corrective action",\n                        "reasoning": "Deviation recorded with no CAPA initiated",\n                        "qualifications": None,\n                    })\n                elif any(kw in tl for kw in ["no deviation", "no deviations",\n                                               "zero deviations"]):\n                    results.append({\n                        "predicate": "deviation_without_capa", "value": False,\n                        "confidence": 0.88,\n                        "evidence": "no deviations recorded",\n                        "reasoning": "Negation: no deviations recorded",\n                        "qualifications": None,\n                    })\n\n            if any(kw in tl for kw in ["contamination detected", "contamination found",\n                                         "particulate matter", "glass particles",\n                                         "microbial contamination"]):\n                results.append({\n                    "predicate": "contamination_detected", "value": True,\n                    "confidence": 0.94,\n                    "evidence": "contamination detected",\n                    "reasoning": "Document explicitly states contamination was found",\n                    "qualifications": None,\n                })\n            elif any(kw in tl for kw in ["no contamination", "contamination-free",\n                                           "no particulate"]):\n                results.append({\n                    "predicate": "contamination_detected", "value": False,\n                    "confidence": 0.90,\n                    "evidence": "no contamination detected",\n                    "reasoning": "Explicit statement that no contamination was found",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["data integrity", "records falsified",\n                                         "data manipulation", "falsification",\n                                         "altered records", "backdated"]):\n                results.append({\n                    "predicate": "data_integrity_failure", "value": True,\n                    "confidence": 0.93,\n                    "evidence": "data integrity violation identified",\n                    "reasoning": "Document references data falsification or manipulation",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["sterility failure", "sterility test failure",\n                                         "non-sterile", "failed sterility"]):\n                results.append({\n                    "predicate": "sterility_assurance_failure", "value": True,\n                    "confidence": 0.94,\n                    "evidence": "sterility failure",\n                    "reasoning": "Sterility test failure explicitly stated",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["out of specification", "oos result",\n                                         "failed dissolution", "below specification",\n                                         "exceeds limit"]):\n                results.append({\n                    "predicate": "oos_result", "value": True,\n                    "confidence": 0.92,\n                    "evidence": "out of specification result",\n                    "reasoning": "OOS result explicitly documented",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["gmp compliant", "gmp compliance confirmed",\n                                         "manufacturing standards met",\n                                         "pre-approval inspection"]):\n                results.append({\n                    "predicate": "gmp_compliant", "value": True,\n                    "confidence": 0.90,\n                    "evidence": "GMP compliance confirmed",\n                    "reasoning": "Explicit confirmation of GMP compliance",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["fda approved", "drug application approved",\n                                         "nda approved", "anda approved",\n                                         "approval granted"]):\n                results.append({\n                    "predicate": "drug_approved", "value": True,\n                    "confidence": 0.97,\n                    "evidence": "FDA drug approval",\n                    "reasoning": "Document states FDA approved this drug application",\n                    "qualifications": None,\n                })\n\n            # ── FDA Device text predicates ────────────────────────────\n            if any(kw in tl for kw in ["no predicate", "no legally marketed",\n                                         "predicate not identified",\n                                         "predicate device not found"]):\n                results.append({\n                    "predicate": "no_predicate_device", "value": True,\n                    "confidence": 0.92,\n                    "evidence": "no predicate device",\n                    "reasoning": "No predicate device identified for 510k",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["substantially equivalent",\n                                         "sese", "device cleared",\n                                         "510k cleared"]):\n                results.append({\n                    "predicate": "device_cleared", "value": True,\n                    "confidence": 0.96,\n                    "evidence": "substantially equivalent — device cleared",\n                    "reasoning": "FDA found device substantially equivalent",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["not substantially equivalent",\n                                         "sesd", "not cleared",\n                                         "510k denied"]):\n                results.append({\n                    "predicate": "substantial_equivalence_not_demonstrated",\n                    "value": True,\n                    "confidence": 0.95,\n                    "evidence": "not substantially equivalent",\n                    "reasoning": "FDA found device NOT substantially equivalent",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["software deficiency", "software failure",\n                                         "algorithm error", "software defect",\n                                         "firmware error"]):\n                results.append({\n                    "predicate": "software_validation_incomplete", "value": True,\n                    "confidence": 0.91,\n                    "evidence": "software deficiency identified",\n                    "reasoning": "Software deficiency in device",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["risk management absent",\n                                         "no risk management",\n                                         "iso 14971 not applied"]):\n                results.append({\n                    "predicate": "risk_management_absent", "value": True,\n                    "confidence": 0.90,\n                    "evidence": "risk management absent",\n                    "reasoning": "Risk management documentation not present",\n                    "qualifications": None,\n                })\n\n            # ── Clinical text predicates ──────────────────────────────\n            if any(kw in tl for kw in ["results not posted", "no results submitted",\n                                         "results not submitted",\n                                         "fdaaa violation", "overdue results",\n                                         "results: no"]):\n                results.append({\n                    "predicate": "results_not_posted", "value": True,\n                    "confidence": 0.94,\n                    "evidence": "results not posted to ClinicalTrials.gov",\n                    "reasoning": "FDAAA 801 results posting violation",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["results posted", "results submitted",\n                                         "results available",\n                                         "has results: yes"]):\n                results.append({\n                    "predicate": "clinical_results_posted", "value": True,\n                    "confidence": 0.95,\n                    "evidence": "results posted",\n                    "reasoning": "Results available on ClinicalTrials.gov",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["safety termination", "adverse events",\n                                         "stopped due to safety",\n                                         "serious adverse", "hepatotoxicity",\n                                         "serious harm", "unexpected toxicity"]):\n                results.append({\n                    "predicate": "safety_termination", "value": True,\n                    "confidence": 0.92,\n                    "evidence": "trial terminated due to safety concerns",\n                    "reasoning": "Trial stopped due to safety signal",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["protocol violation", "irb violation",\n                                         "non-compliance identified",\n                                         "protocol non-compliance"]):\n                results.append({\n                    "predicate": "protocol_violation", "value": True,\n                    "confidence": 0.91,\n                    "evidence": "protocol violation identified",\n                    "reasoning": "Protocol or IRB violation documented",\n                    "qualifications": None,\n                })\n\n            # ── SEC text predicates ───────────────────────────────────\n            # Check negation FIRST — "no material weakness" must not also\n            # trigger "material_weakness_not_disclosed = True"\n            no_material_weakness = any(kw in tl for kw in [\n                "no material weakness", "no material weaknesses",\n                "controls effective", "internal controls are effective",\n                "sox controls effective",\n            ])\n\n            if not no_material_weakness and any(kw in tl for kw in [\n                "material weakness", "material weaknesses",\n                "material weakness identified",\n            ]):\n                results.append({\n                    "predicate": "material_weakness_not_disclosed",\n                    "value": True,\n                    "confidence": 0.93,\n                    "evidence": "material weakness identified",\n                    "reasoning": "Material weakness in internal controls",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["restatement", "restate", "restated",\n                                         "financial restatement required"]):\n                results.append({\n                    "predicate": "financial_restatement", "value": True,\n                    "confidence": 0.95,\n                    "evidence": "financial restatement required",\n                    "reasoning": "Prior financial statements required restatement",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["going concern", "substantial doubt about",\n                                         "going concern doubt",\n                                         "going concern risk"]):\n                # Only flag if NOT negated (e.g. "no going concern")\n                if not any(neg in tl for neg in ["no going concern",\n                                                   "not a going concern",\n                                                   "going concern not applicable"]):\n                    results.append({\n                        "predicate": "going_concern_not_disclosed", "value": True,\n                        "confidence": 0.92,\n                        "evidence": "going concern doubt",\n                        "reasoning": "Going concern risk identified",\n                        "qualifications": None,\n                    })\n\n            if any(kw in tl for kw in ["no material weakness",\n                                         "controls effective",\n                                         "internal controls are effective",\n                                         "no material weaknesses"]):\n                results.append({\n                    "predicate": "sox_controls_effective", "value": True,\n                    "confidence": 0.91,\n                    "evidence": "internal controls effective",\n                    "reasoning": "Management confirmed effective controls",\n                    "qualifications": None,\n                })\n\n            if any(kw in tl for kw in ["clean audit opinion",\n                                         "unqualified opinion",\n                                         "unqualified audit"]):\n                results.append({\n                    "predicate": "clean_audit_opinion", "value": True,\n                    "confidence": 0.93,\n                    "evidence": "clean audit opinion",\n                    "reasoning": "External auditor issued unqualified opinion",\n                    "qualifications": None,\n                })\n\n            return json.dumps(results)\n\n        return "{}"\n'

_FILES['extraction/verifier.py'] = '"""\nregintel_engine.extraction.verifier\n=====================================\nHallucination verification, normalization, and fact building.\n\nThree components:\n  HallucinationVerifier  checks every extracted fact is grounded in document\n  FactNormalizer         maps document language to standard vocabulary names\n  FactDictBuilder        assembles verified facts into FactDict for engine\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport re\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom ..models import ExtractedFact, FactDict\nfrom ..vocabulary import EncodingTables, PredicateVocabulary\n\nlog = logging.getLogger("regintel.verifier")\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  HALLUCINATION VERIFIER\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass HallucinationVerifier:\n    """\n    Verifies every extracted fact is grounded in the source document.\n\n    Three checks:\n    1. extracted_text exists verbatim in document\n    2. numeric value appears in extracted_text\n    3. boolean facts have explicit PASS/FAIL signal in extracted_text\n\n    Result buckets:\n      confidence >= 0.90, no flags → accept\n      confidence 0.60-0.90          → accept with flag\n      confidence < 0.60             → reject (treat as absent)\n      not grounded in document      → reject (hallucinated)\n\n    CRITICAL: unverified facts never reach the symbolic engine.\n    A hallucinated fact could cause a wrong verdict.\n    """\n\n    # Explicit signals for boolean pass/fail\n    PASS_SIGNALS = {"pass", "compliant", "within specification", "within spec",\n                    "cleared", "approved", "current", "valid", "satisfactory",\n                    "adequate", "effective", "met", "achieved"}\n\n    FAIL_SIGNALS = {"fail", "non-compliant", "out of specification", "oos",\n                    "overdue", "expired", "absent", "missing", "not found",\n                    "not received", "not on file", "not documented",\n                    "violation", "recalled", "terminated", "inadequate"}\n\n    CONFIDENCE_ACCEPT  = 0.90\n    CONFIDENCE_FLAG    = 0.60\n\n    def verify(\n        self,\n        facts:    List[ExtractedFact],\n        document: str,\n    ) -> Tuple[List[ExtractedFact], List[str]]:\n        """\n        Verify facts against document.\n        Returns (verified_facts, rejection_log).\n        verified_facts may have reduced confidence if checks fail.\n        """\n        doc_lower  = document.lower()\n        accepted   = []\n        rejected   = []\n\n        for fact in facts:\n            result, reason = self._check(fact, document, doc_lower)\n            if result == "accept":\n                accepted.append(fact)\n            elif result == "flag":\n                fact.confidence = max(fact.confidence * 0.7, self.CONFIDENCE_FLAG)\n                accepted.append(fact)\n            else:\n                rejected.append(f"{fact.name}: {reason}")\n                log.debug(f"[VERIFIER] Rejected {fact.name}: {reason}")\n\n        return accepted, rejected\n\n    def _check(\n        self,\n        fact:      ExtractedFact,\n        document:  str,\n        doc_lower: str,\n    ) -> Tuple[str, str]:  # (accept|flag|reject, reason)\n        """Run all verification checks on one fact."""\n        extracted = fact.extracted_text.strip()\n\n        # Check 1: extracted_text must exist in document\n        # Skip verbatim check for very short extractions (< 20 chars) because:\n        # - Short phrases match in many forms ("Class II" vs "class ii device")\n        # - Real LLMs sometimes paraphrase short values\n        # - Numeric/boolean checks below provide the actual signal\n        if extracted and len(extracted) >= 20:\n            if extracted.lower() not in doc_lower:\n                # Try partial match (first 50 chars of longer extractions)\n                if len(extracted) > 50:\n                    partial = extracted[:50].lower()\n                    if partial not in doc_lower:\n                        return "reject", "extracted_text not found in document (hallucinated)"\n                else:\n                    return "reject", "extracted_text not found in document (hallucinated)"\n\n        # Check 2: numeric values must appear in extracted_text\n        if isinstance(fact.value, (int, float)):\n            val_str = str(fact.value)\n            if val_str not in extracted and val_str not in document[:5000]:\n                return "flag", f"numeric value {val_str} not found in extracted_text"\n\n        # Check 3: boolean facts need explicit signal\n        if isinstance(fact.value, bool) and extracted:\n            text_lower = extracted.lower()\n            has_pass   = any(sig in text_lower for sig in self.PASS_SIGNALS)\n            has_fail   = any(sig in text_lower for sig in self.FAIL_SIGNALS)\n\n            if fact.value is True and not has_pass:\n                return "flag", "boolean True but no explicit PASS signal in text"\n            if fact.value is False and not has_fail:\n                return "flag", "boolean False but no explicit FAIL signal in text"\n\n        # Check 4: confidence threshold\n        if fact.confidence < self.CONFIDENCE_FLAG:\n            return "reject", f"confidence {fact.confidence:.2f} below threshold"\n\n        return "accept", "ok"\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  FACT NORMALIZER\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass FactNormalizer:\n    """\n    Maps document language variations to standard vocabulary names,\n    including positive/negative framing inversion.\n\n    The LLM extraction prompt returns positively-framed booleans\n    (e.g. calibration_current=True/False) while the controlled vocabulary\n    uses violation-signal names (calibration_expired=True/False).\n\n    Two types of mapping are handled:\n    1. ALIASES: name-only rename (same polarity)\n       coa_reviewed → api_coa_reviewed\n    2. INVERTED: name rename + value inversion (polarity flip)\n       calibration_current=True  → calibration_expired=False\n       calibration_current=False → calibration_expired=True\n    """\n\n    # Direct aliases: document term → standard vocabulary name (same polarity)\n    ALIASES: Dict[str, str] = {\n        "coa_reviewed":                       "api_coa_reviewed",\n        "certificate_of_analysis_reviewed":   "api_coa_reviewed",\n        "raw_material_released":              "api_coa_reviewed",\n        "api_released":                       "api_coa_reviewed",\n        "equipment_calibration_current":      "calibration_current",\n        "calibration_valid":                  "calibration_current",\n        "instrument_calibration_current":     "calibration_current",\n        "process_parameters_in_spec":         "process_in_spec",\n        "manufacturing_in_spec":              "process_in_spec",\n        "critical_process_parameters_met":    "process_in_spec",\n        "sample_size":                        "clinical_n",\n        "enrollment_count":                   "clinical_n",\n        "subjects_enrolled":                  "clinical_n",\n        "n_subjects":                         "clinical_n",\n        "participants":                       "clinical_n",\n        "predicate_k_number":                 "predicate_device",\n        "substantially_equivalent_predicate": "predicate_device",\n        "legally_marketed_predicate":         "predicate_device",\n        "iso_14971_applied":                  "risk_management_standard",\n        "risk_management_documented":         "risk_management_standard",\n        "risk_file_present":                  "risk_management_standard",\n    }\n\n    # Inverted aliases: document name → (vocabulary name, invert_value)\n    # When invert_value=True, the boolean is flipped before storing.\n    # Used when LLM uses positive assertions but vocab uses violation signals.\n    INVERTED: Dict[str, tuple] = {\n        # calibration_current=False → calibration_expired=True\n        "calibration_current":      ("calibration_expired", True),\n        # api_coa_reviewed=True → api_coa_missing=False\n        "api_coa_reviewed":         ("api_coa_missing",     True),\n        # process_in_spec=False → oos_result=True\n        "process_in_spec":          ("oos_result",          True),\n        # dissolution_pass=False → oos_result=True\n        "dissolution_pass":         ("oos_result",          True),\n        # sterility_tested=True → sterility_assurance_failure=False\n        "sterility_tested":         ("sterility_assurance_failure", True),\n    }\n\n    def normalize_name(self, name: str) -> str:\n        """Map fact name to standard vocabulary name (aliases only)."""\n        # Direct alias lookup\n        if name in self.ALIASES:\n            return self.ALIASES[name]\n        # Snake-case normalise then lookup\n        norm = re.sub(r"[^a-z0-9_]", "_", name.lower())\n        norm = re.sub(r"_+", "_", norm).strip("_")\n        return self.ALIASES.get(norm, norm)\n\n    def normalize_all(self, facts: List[ExtractedFact]) -> List[ExtractedFact]:\n        """\n        Normalize all fact names and apply value inversions where needed.\n\n        After inversion, `calibration_current=False` becomes\n        `calibration_expired=True` — the vocabulary predicate name\n        with the correct polarity.\n        """\n        result = []\n        for fact in facts:\n            # Check for inversion mapping first\n            if fact.name in self.INVERTED:\n                vocab_name, should_invert = self.INVERTED[fact.name]\n                if should_invert and isinstance(fact.value, bool):\n                    fact.value = not fact.value\n                fact.name = vocab_name\n            else:\n                # Plain alias\n                fact.name = self.normalize_name(fact.name)\n            result.append(fact)\n        return result\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  FACT DICT BUILDER\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass FactDictBuilder:\n    """\n    Assembles verified, normalized ExtractedFacts into a FactDict\n    that the symbolic rule engine can evaluate.\n\n    INVARIANT: no neural floats, no embeddings, no probabilities in FactDict.\n    Only discrete values with full provenance.\n\n    vocab_names: set of controlled vocabulary predicate names.\n    Only predicates in this set are included in the ILP sparse dict.\n    This prevents noise facts (brand_name, sponsor, etc.) from\n    contaminating ILP training with spurious correlations.\n    """\n\n    def __init__(\n        self,\n        encoding_tables: Optional[EncodingTables] = None,\n        vocab_names:     Optional[set] = None,\n    ) -> None:\n        self.encoding    = encoding_tables or EncodingTables()\n        self.vocab_names = vocab_names     # set of controlled predicate names\n\n    def build(\n        self,\n        structured_facts:    List[ExtractedFact],\n        text_predicate_facts: List[ExtractedFact],\n        domain:              str,\n    ) -> FactDict:\n        """\n        Build a FactDict from verified structured and text predicate facts.\n\n        Structured facts: keep original discrete values (bool, str, int)\n        Text predicate facts: already boolean from classifier\n        Both: low-confidence facts go to absent_facts list\n        """\n        facts_dict = {}\n        provenance = {}\n        absent     = []\n\n        all_facts = structured_facts + text_predicate_facts\n\n        for fact in all_facts:\n            if fact.low_confidence:\n                # Uncertain — treat as absent (→ None → NEEDS_REVIEW not NON_COMPLIANT)\n                absent.append(fact.name)\n                continue\n\n            # Avoid overwriting higher-confidence facts\n            if fact.name in facts_dict:\n                existing_conf = provenance[fact.name].confidence\n                if fact.confidence <= existing_conf:\n                    continue\n\n            facts_dict[fact.name] = fact.value\n            provenance[fact.name] = fact\n\n        return FactDict(\n            facts        = facts_dict,\n            provenance   = provenance,\n            absent_facts = absent,\n            domain       = domain,\n        )\n\n    def build_ilp_sparse_dict(\n        self,\n        fact_dict: FactDict,\n    ) -> Dict[str, float]:\n        """\n        Convert FactDict to sparse float dict for ILP training.\n\n        Only vocabulary predicates are included — this prevents noise\n        facts (brand_name, sponsor, application_number, etc.) from\n        appearing in ILP and creating spurious rules.\n\n        Absent facts NOT included (not padded with 0.5).\n        ILP mask: present = scored, absent = excluded from this document.\n        """\n        sparse: Dict[str, float] = {}\n\n        for name, value in fact_dict.facts.items():\n            # Skip any fact that is not in the controlled vocabulary\n            if self.vocab_names is not None and name not in self.vocab_names:\n                continue\n\n            encoded = self.encoding.encode(name, value)\n            if encoded is not None:\n                sparse[name] = encoded\n\n        return sparse\n'

_FILES['ilp/__init__.py'] = '"""regintel_engine.ilp"""'

_FILES['ilp/sparse_ilp.py'] = '"""\nregintel_engine.ilp.sparse_ilp\n================================\nDomain-constrained sparse ILP for rule discovery.\n\nKey design decisions (from architecture planning)\n-------------------------------------------------\n1. ILP trains on real extracted facts — not JEPA embeddings\n   This guarantees discovered rules check real extractable fields\n\n2. Domain constraint: predicates from different domains cannot\n   appear in the same rule body. Prevents spurious correlations.\n   e.g. GMP calibration + clinical trial enrollment = nonsense rule\n\n3. Sparse representation: absent facts excluded from scoring entirely\n   (not padded with 0.5). ILP only learns from facts actually present\n   in each document, which varies by document type.\n\n4. Gradient descent with L1 regularization to discover sparse rule bodies.\n   Most compliance rules involve 1-3 predicates, not 50.\n\n5. Human-readable output: predicate names come from the controlled vocabulary\n   so discovered rules are immediately comprehensible.\n\nArchitecture of sparse ILP\n--------------------------\nInput:  N documents × M predicates (sparse — absent = not scored)\n        N × 1 labels (0=NON_COMPLIANT, 1=COMPLIANT)\n\nFor each head (compliant, non_compliant):\n  - Learn a weight vector W of shape (M,)\n  - score(doc) = sum(W[i] * value[i] for i in present_predicates)\n  - Rule fires when score > threshold\n  - L1 regularization → sparse W → few predicates per rule\n\nExtract rules from converged weights:\n  - Top-k predicates per head = rule body\n  - Confidence = precision on training set\n  - Coverage = recall on positive class\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport math\nimport random\nfrom dataclasses import dataclass, field\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom ..models import HornClause\nfrom ..vocabulary import PredicateVocabulary\n\nlog = logging.getLogger("regintel.ilp")\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  ILP CONFIGURATION\n# ─────────────────────────────────────────────────────────────────────────────\n\n@dataclass\nclass ILPConfig:\n    n_epochs:          int   = 200\n    learning_rate:     float = 0.05\n    l1_lambda:         float = 0.01   # sparsity regularization\n    threshold:         float = 0.0    # decision boundary (unused — kept for API compat)\n    top_k_predicates:  int   = 3      # max predicates per rule body\n    min_confidence:    float = 0.75   # minimum rule precision\n    min_coverage:      float = 0.10   # minimum recall\n    min_support:       int   = 5      # minimum supporting documents\n    score_scale:       float = 1.0    # sigmoid input scale factor.\n    # score_scale > 1 → steeper sigmoid (more decisive).\n    # score_scale < 1 → shallower sigmoid (softer gradients).\n    # Default 1.0 = standard logistic regression.\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  SPARSE ILP\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass SparseILP:\n    """\n    Domain-constrained sparse ILP for compliance rule discovery.\n\n    Trains on (sparse_fact_dict, label) pairs.\n    Discovers Horn clauses within a single regulatory domain.\n    Produces human-readable rules using controlled vocabulary names.\n\n    Pure Python/stdlib — no torch dependency.\n    Uses simple gradient descent with sigmoid activation.\n    """\n\n    def __init__(\n        self,\n        vocab:  PredicateVocabulary,\n        config: Optional[ILPConfig] = None,\n    ) -> None:\n        self.vocab  = vocab\n        self.config = config or ILPConfig()\n\n    def induce(\n        self,\n        examples: List[Dict[str, Any]],\n        domain:   str,\n    ) -> List[HornClause]:\n        """\n        Discover compliance rules from labeled examples.\n\n        Parameters\n        ----------\n        examples  List of {"facts": sparse_dict, "label": "COMPLIANT"|"NON_COMPLIANT"}\n        domain    Regulatory domain to constrain predicate vocabulary\n\n        Returns\n        -------\n        List of HornClause objects (pending SME approval)\n        """\n        if not examples:\n            return []\n\n        # Get domain-specific predicates\n        domain_preds = self.vocab.get_names(domain)\n        if not domain_preds:\n            log.warning(f"[ILP] No predicates for domain: {domain}")\n            return []\n\n        # Build data matrix\n        X, y, pred_names = self._build_matrix(examples, domain_preds)\n\n        if len(X) < self.config.min_support * 2:\n            log.warning(f"[ILP] Too few examples ({len(X)}) for domain {domain}")\n            return []\n\n        n_pos = sum(1 for yi in y if yi == 1)\n        n_neg = len(y) - n_pos\n        log.info(f"[ILP] domain={domain} examples={len(X)} "\n                 f"preds={len(pred_names)} pos={n_pos} neg={n_neg}")\n\n        clauses = []\n\n        # Discover rules for both heads\n        for head, target_label in [("non_compliant", 0), ("compliant", 1)]:\n            head_clauses = self._discover_for_head(\n                X, y, pred_names, head, target_label, domain)\n            clauses.extend(head_clauses)\n\n        log.info(f"[ILP] domain={domain} discovered {len(clauses)} clauses")\n        return clauses\n\n    def _build_matrix(\n        self,\n        examples:     List[Dict[str, Any]],\n        domain_preds: List[str],\n    ) -> Tuple[List[List[Tuple[int, float]]], List[int], List[str]]:\n        """\n        Build sparse matrix representation.\n        Each row is a list of (predicate_index, value) for present predicates.\n        """\n        # Only include predicates that appear in at least 2 examples\n        pred_counts: Dict[str, int] = {}\n        for ex in examples:\n            for pred in ex["facts"]:\n                if pred in domain_preds:\n                    pred_counts[pred] = pred_counts.get(pred, 0) + 1\n\n        active_preds = [p for p, c in pred_counts.items()\n                        if c >= max(2, self.config.min_support)]\n\n        if not active_preds:\n            # Fall back to all domain predicates\n            active_preds = domain_preds\n\n        pred_idx = {p: i for i, p in enumerate(active_preds)}\n\n        X = []\n        y = []\n        for ex in examples:\n            row = []\n            for pred, val in ex["facts"].items():\n                if pred in pred_idx and isinstance(val, (int, float)):\n                    row.append((pred_idx[pred], float(val)))\n            if row:\n                X.append(row)\n                y.append(1 if ex["label"] == "COMPLIANT" else 0)\n\n        return X, y, active_preds\n\n    def _discover_for_head(\n        self,\n        X:            List[List[Tuple[int, float]]],\n        y:            List[int],\n        pred_names:   List[str],\n        head:         str,\n        target_label: int,\n        domain:       str,\n    ) -> List[HornClause]:\n        """Run gradient descent to find predicates predicting target_label."""\n        n_preds = len(pred_names)\n        n_docs  = len(X)\n\n        if n_preds == 0:\n            return []\n\n        # Initialize weights\n        weights = [random.gauss(0, 0.01) for _ in range(n_preds)]\n\n        cfg = self.config\n\n        for epoch in range(cfg.n_epochs):\n            grad = [0.0] * n_preds\n            loss = 0.0\n\n            for i, (row, label) in enumerate(zip(X, y)):\n                # Forward pass: score = sum(w[j] * x[j]) for present predicates\n                score = sum(weights[j] * v for j, v in row)\n                score = score * cfg.score_scale\n\n                # Sigmoid (numerically stable)\n                if score >= 0:\n                    sig = 1.0 / (1.0 + math.exp(-min(score, 500)))\n                else:\n                    ex  = math.exp(min(score, 500))\n                    sig = ex / (1.0 + ex)\n\n                target = float(label == target_label)\n                error  = sig - target\n\n                # Clamp for stability\n                error = max(-10.0, min(10.0, error))\n\n                loss += -(target * math.log(max(sig, 1e-10)) +\n                          (1 - target) * math.log(max(1 - sig, 1e-10)))\n\n                # Backward pass — gradient w.r.t. weights\n                for j, v in row:\n                    grad[j] += error * v * cfg.score_scale\n\n            # L1 regularization gradient\n            for j in range(n_preds):\n                if weights[j] > 0:\n                    grad[j] += cfg.l1_lambda\n                elif weights[j] < 0:\n                    grad[j] -= cfg.l1_lambda\n\n            # Update weights\n            lr = cfg.learning_rate / max(1, epoch // 50 + 1)\n            for j in range(n_preds):\n                weights[j] -= lr * grad[j] / n_docs\n\n        # Extract top-k predicates by absolute weight\n        indexed = sorted(\n            enumerate(weights),\n            key=lambda x: -abs(x[1]),\n        )\n\n        # Both heads: predicates that predict the target have POSITIVE weights.\n        #\n        # Why? For target_label=0 (non_compliant):\n        #   NC doc → target=1.0, error = sig-1.0 < 0 → negative grad\n        #   → weight INCREASES toward positive territory\n        # For target_label=1 (compliant):\n        #   C doc → target=1.0, same logic → weight INCREASES\n        # In both cases the predicates correlated with the target\n        # end up with POSITIVE weights after training.\n        top_k = [(j, w) for j, w in indexed\n                 if w > 0.05][:cfg.top_k_predicates]\n\n        if not top_k:\n            return []\n\n        body_preds = [pred_names[j] for j, _ in top_k]\n\n        # Check domain constraint\n        if not self.vocab.check_cross_domain(body_preds):\n            log.debug(f"[ILP] Cross-domain rule rejected: {body_preds}")\n            return []\n\n        # Evaluate rule on training data\n        confidence, coverage, support = self._evaluate_rule(\n            body_preds, head, target_label, X, y, pred_names)\n\n        if (confidence < cfg.min_confidence\n                or coverage < cfg.min_coverage\n                or support < cfg.min_support):\n            return []\n\n        import uuid\n        clause_id = (f"HC-{domain[:3].upper()}-"\n                     f"{uuid.uuid4().hex[:8].upper()}")\n\n        return [HornClause(\n            clause_id  = clause_id,\n            head       = head,\n            body       = body_preds,\n            confidence = round(confidence, 3),\n            coverage   = round(coverage, 3),\n            support    = support,\n            domain     = domain,\n        )]\n\n    def _evaluate_rule(\n        self,\n        body_preds:   List[str],\n        head:         str,\n        target_label: int,\n        X:            List[List[Tuple[int, float]]],\n        y:            List[int],\n        pred_names:   List[str],\n    ) -> Tuple[float, float, int]:\n        """\n        Compute precision, recall, and support for a rule body.\n        Returns (confidence, coverage, support).\n        """\n        pred_set = set(pred_names.index(p) for p in body_preds\n                       if p in pred_names)\n        if not pred_set:\n            return 0.0, 0.0, 0\n\n        tp = fp = fn = 0\n\n        for row, label in zip(X, y):\n            present_idx = {j for j, _ in row}\n            # AND logic: rule fires only when ALL body predicates are present.\n            # intersection() gives OR — issubset() gives AND (correct).\n            fires = pred_set.issubset(present_idx)\n\n            if fires and label == target_label:\n                tp += 1\n            elif fires and label != target_label:\n                fp += 1\n            elif not fires and label == target_label:\n                fn += 1\n\n        if tp + fp == 0:\n            return 0.0, 0.0, 0\n\n        precision = tp / (tp + fp)\n        recall    = tp / max(tp + fn, 1)\n        support   = tp\n\n        return precision, recall, support\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  DREAMCODER\n# ─────────────────────────────────────────────────────────────────────────────\n\n@dataclass\nclass Primitive:\n    """A reusable abstraction promoted from recurring predicate combinations."""\n    name:        str\n    predicates:  List[str]\n    domain:      str\n    frequency:   int\n    description: str = ""\n\n\nclass DreamCoder:\n    """\n    Abstracts recurring predicate combinations into reusable primitives.\n\n    Counts how often predicate combinations co-occur across discovered rules.\n    Promotes high-frequency combinations to primitives.\n    Future ILP cycles can use primitives as single units.\n\n    Example:\n      api_coa_missing + deviation_without_capa appear together in 31 rules\n      → promoted to primitive: gmp_documentation_failure\n      Future rules: "non_compliant :- gmp_documentation_failure"\n      More expressive, fewer terms, same meaning.\n    """\n\n    MIN_FREQUENCY = 3   # minimum co-occurrences to promote to primitive\n\n    def __init__(self) -> None:\n        self.primitives: Dict[str, Primitive] = {}\n        self.library:    List[Primitive]      = []\n\n    def wake(self, clauses: List[HornClause]) -> List[Primitive]:\n        """\n        Wake phase: find recurring predicate combinations across rules.\n        Returns newly discovered primitives.\n        """\n        # Count co-occurrences of predicate pairs across rule bodies\n        pair_counts: Dict[Tuple, int] = {}\n        for clause in clauses:\n            body = sorted(clause.body)\n            for i in range(len(body)):\n                for j in range(i + 1, len(body)):\n                    pair = (body[i], body[j], clause.domain)\n                    pair_counts[pair] = pair_counts.get(pair, 0) + 1\n\n        # Also count single-predicate frequencies\n        single_counts: Dict[Tuple, int] = {}\n        for clause in clauses:\n            for pred in clause.body:\n                key = (pred, clause.domain)\n                single_counts[key] = single_counts.get(key, 0) + 1\n\n        new_primitives = []\n\n        # Promote pairs that co-occur frequently\n        for (p1, p2, domain), count in pair_counts.items():\n            if count >= self.MIN_FREQUENCY:\n                prim_name = f"{domain[:3]}_{\'_\'.join(sorted([p1, p2]))[:40]}"\n                if prim_name not in self.primitives:\n                    prim = Primitive(\n                        name       = prim_name,\n                        predicates = [p1, p2],\n                        domain     = domain,\n                        frequency  = count,\n                        description = f"Co-occurring {domain} pattern: {p1} + {p2}",\n                    )\n                    self.primitives[prim_name] = prim\n                    self.library.append(prim)     # FIX: also populate library\n                    new_primitives.append(prim)\n\n        # Promote single predicates that appear in many rules\n        for (pred, domain), count in single_counts.items():\n            if count >= self.MIN_FREQUENCY * 2:\n                prim_name = f"{domain[:3]}_{pred}"\n                if prim_name not in self.primitives:\n                    prim = Primitive(\n                        name        = prim_name,\n                        predicates  = [pred],\n                        domain      = domain,\n                        frequency   = count,\n                        description = f"High-frequency {domain} predicate: {pred}",\n                    )\n                    self.primitives[prim_name] = prim\n                    self.library.append(prim)     # FIX: also populate library\n                    new_primitives.append(prim)\n\n        log.info(f"[DreamCoder] wake: {len(new_primitives)} new primitives "\n                 f"(total {len(self.primitives)})")\n        return new_primitives\n\n    def sleep(self, clauses: List[HornClause]) -> List[HornClause]:\n        """\n        Sleep phase: rewrite rule bodies using primitive names.\n        More expressive rules with fewer terms.\n        """\n        if not self.primitives:\n            return clauses\n\n        compressed = []\n        for clause in clauses:\n            new_body = self._compress_body(clause.body, clause.domain)\n            if new_body != clause.body:\n                log.debug(f"[DreamCoder] compressed {clause.body} → {new_body}")\n            new_clause           = HornClause(\n                clause_id  = clause.clause_id,\n                head       = clause.head,\n                body       = new_body,\n                confidence = clause.confidence,\n                coverage   = clause.coverage,\n                support    = clause.support,\n                domain     = clause.domain,\n            )\n            compressed.append(new_clause)\n\n        return compressed\n\n    def _compress_body(self, body: List[str], domain: str) -> List[str]:\n        """Replace predicate pairs with primitive names where available."""\n        body_set = set(body)\n        result   = list(body)\n\n        for prim in self.primitives.values():\n            if prim.domain != domain:\n                continue\n            if all(p in body_set for p in prim.predicates):\n                # Replace predicates with primitive\n                result = [p for p in result if p not in prim.predicates]\n                result.append(prim.name)\n                body_set -= set(prim.predicates)\n                body_set.add(prim.name)\n                break   # one substitution at a time\n\n        return result\n'

