_FILES['rules/engine.py'] = '"""\nregintel_engine.rules\n======================\nBase rules, rule compiler, and symbolic rule engine.\n\nThree components:\n\n1. BASE_RULES\n   Hand-written by SME. Cover known regulatory requirements.\n   Always present regardless of training data.\n   Never discovered by ILP — written by regulatory experts.\n\n2. RuleCompiler\n   Converts HornClause → ComplianceRule (compiled Python function).\n   The compiled_check function is pure Python:\n     Input:  FactDict\n     Output: Optional[bool]  (True=pass, False=fail, None=uncertain)\n   Zero neural involvement.\n\n3. SymbolicRuleEngine\n   Evaluates all rules against a FactDict.\n   Three-valued logic:\n     True  = passed\n     False = confirmed violation → may trigger NON_COMPLIANT\n     None  = uncertain → NEEDS_REVIEW\n   Verdict logic:\n     any critical rule = False → NON_COMPLIANT\n     any critical rule = None  → NEEDS_REVIEW\n     all rules = True          → COMPLIANT\n"""\n\nfrom __future__ import annotations\n\nimport logging\nfrom datetime import datetime\nfrom typing import Any, Callable, Dict, List, Optional, Tuple\n\nfrom ..models import (\n    ComplianceRule, FactDict, HornClause, RuleResult, Verdict,\n)\nfrom ..vocabulary import PredicateVocabulary\n\nlog = logging.getLogger("regintel.rules")\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  BASE RULES\n# ─────────────────────────────────────────────────────────────────────────────\n\ndef _make_gmp_rules(vocab: PredicateVocabulary) -> List[ComplianceRule]:\n    """Hand-written GMP compliance rules based on 21 CFR Part 211."""\n\n    rules = []\n\n    def r(rule_id, name, severity, predicates, check_fn,\n          pass_msg, fail_msg, reg, reg_text, reg_url):\n        rule = ComplianceRule(\n            rule_id         = rule_id,\n            name            = name,\n            domain          = "gmp",\n            severity        = severity,\n            rule_source     = "base",\n            regulation      = reg,\n            regulation_text = reg_text,\n            regulation_url  = reg_url,\n            pass_message    = pass_msg,\n            fail_message    = fail_msg,\n            predicates      = predicates,\n        )\n        rule.compiled_check = check_fn\n        return rule\n\n    # GMP-001: CoA must not be missing\n    rule = ComplianceRule(\n        rule_id         = "GMP-001",\n        name            = "Raw material certificate of analysis verification",\n        domain          = "gmp",\n        severity        = "critical",\n        rule_source     = "base",\n        regulation      = "21 CFR 211.84(d)(1)",\n        regulation_text = "Each lot of components shall be withheld from use until sampled, tested and released by the quality control unit.",\n        regulation_url  = "https://www.ecfr.gov/current/title-21/section-211.84",\n        pass_message    = "API CoA reviewed and approved prior to manufacturing",\n        fail_message    = "API Certificate of Analysis missing — batch cannot be released",\n        predicates      = ["api_coa_missing"],\n    )\n    # api_coa_missing=False → CoA was present → pass\n    # api_coa_missing=True  → CoA was missing → fail\n    # api_coa_missing=None  → unknown         → uncertain\n    rule.compiled_check = lambda f: (\n        None if f.get("api_coa_missing") is None\n        else not bool(f.get("api_coa_missing"))\n    )\n    rules.append(rule)\n\n    # GMP-002: Equipment calibration must not be expired\n    rule = ComplianceRule(\n        rule_id         = "GMP-002",\n        name            = "Equipment calibration current",\n        domain          = "gmp",\n        severity        = "major",\n        rule_source     = "base",\n        regulation      = "21 CFR 211.68(a)",\n        regulation_text = "Equipment shall be routinely calibrated, inspected, or checked according to a written program.",\n        regulation_url  = "https://www.ecfr.gov/current/title-21/section-211.68",\n        pass_message    = "All equipment calibration is current",\n        fail_message    = "Equipment calibration overdue — process data may be unreliable",\n        predicates      = ["calibration_expired"],\n    )\n    rule.compiled_check = lambda f: (\n        None if f.get("calibration_expired") is None\n        else not bool(f.get("calibration_expired"))\n    )\n    rules.append(rule)\n\n    # GMP-003: No out-of-specification results\n    rule = ComplianceRule(\n        rule_id         = "GMP-003",\n        name            = "Critical process parameters within specification",\n        domain          = "gmp",\n        severity        = "critical",\n        rule_source     = "base",\n        regulation      = "21 CFR 211.100(a)",\n        regulation_text = "Written procedures for production and process controls shall be established.",\n        regulation_url  = "https://www.ecfr.gov/current/title-21/section-211.100",\n        pass_message    = "All critical process parameters within validated specification",\n        fail_message    = "Out-of-specification result detected — batch integrity compromised",\n        predicates      = ["oos_result"],\n    )\n    rule.compiled_check = lambda f: (\n        None if f.get("oos_result") is None\n        else not bool(f.get("oos_result"))\n    )\n    rules.append(rule)\n\n    # GMP-004: Deviation without CAPA\n    def check_deviation(f: FactDict) -> Optional[bool]:\n        capa_missing = f.get("deviation_without_capa")\n        if capa_missing is None:\n            return None\n        return not bool(capa_missing)   # passes if NO deviation-without-capa\n\n    rule = ComplianceRule(\n        rule_id         = "GMP-004",\n        name            = "All deviations have corrective action",\n        domain          = "gmp",\n        severity        = "critical",\n        rule_source     = "base",\n        regulation      = "21 CFR 211.192",\n        regulation_text = "Any unexplained discrepancy shall be thoroughly investigated.",\n        regulation_url  = "https://www.ecfr.gov/current/title-21/section-211.192",\n        pass_message    = "All manufacturing deviations have documented corrective actions",\n        fail_message    = "Deviation recorded without CAPA — unresolved quality failure",\n        predicates      = ["deviation_without_capa"],\n    )\n    rule.compiled_check = check_deviation\n    rules.append(rule)\n\n    # GMP-005: No contamination\n    def check_contamination(f: FactDict) -> Optional[bool]:\n        contamination = f.get("contamination_detected")\n        if contamination is None:\n            return None\n        return not bool(contamination)\n\n    rule = ComplianceRule(\n        rule_id         = "GMP-005",\n        name            = "No contamination detected in batch",\n        domain          = "gmp",\n        severity        = "critical",\n        rule_source     = "base",\n        regulation      = "21 CFR 211.42",\n        regulation_text = "There shall be separate or defined areas to prevent contamination.",\n        regulation_url  = "https://www.ecfr.gov/current/title-21/section-211.42",\n        pass_message    = "No contamination detected in product",\n        fail_message    = "Contamination detected — batch must be quarantined and investigated",\n        predicates      = ["contamination_detected"],\n    )\n    rule.compiled_check = check_contamination\n    rules.append(rule)\n\n    return rules\n\n\ndef _make_device_rules(vocab: PredicateVocabulary) -> List[ComplianceRule]:\n    """Hand-written FDA 510k rules based on 21 CFR 807 and ISO standards."""\n\n    rules = []\n\n    # DEV-001: Predicate device required for 510k\n    def check_predicate(f: FactDict) -> Optional[bool]:\n        pred = f.get("predicate_device")\n        if pred is None:\n            return None\n        return bool(pred)\n\n    rule = ComplianceRule(\n        rule_id         = "DEV-001",\n        name            = "Predicate device referenced in 510k",\n        domain          = "fda_device",\n        severity        = "critical",\n        rule_source     = "base",\n        regulation      = "21 CFR 807.87(f)",\n        regulation_text = "A 510(k) shall contain a description of how the device compares to the predicate device.",\n        regulation_url  = "https://www.ecfr.gov/current/title-21/section-807.87",\n        pass_message    = "Predicate device identified",\n        fail_message    = "No predicate device — substantial equivalence cannot be demonstrated",\n        predicates      = ["predicate_device"],\n    )\n    rule.compiled_check = check_predicate\n    rules.append(rule)\n\n    # DEV-002: Risk management required\n    def check_risk_mgmt(f: FactDict) -> Optional[bool]:\n        risk = f.get("risk_management_standard")\n        absent = f.get("risk_management_absent")\n\n        if absent is True:\n            return False\n        if risk is not None and "14971" in str(risk):\n            return True\n        if risk is None and absent is None:\n            return None\n        return None\n\n    rule = ComplianceRule(\n        rule_id         = "DEV-002",\n        name            = "Risk management per ISO 14971",\n        domain          = "fda_device",\n        severity        = "major",\n        rule_source     = "base",\n        regulation      = "ISO 14971:2019",\n        regulation_text = "The manufacturer shall establish a process for risk management.",\n        regulation_url  = "https://www.iso.org/standard/72704.html",\n        pass_message    = "ISO 14971 risk management documented",\n        fail_message    = "Risk management absent or not per ISO 14971",\n        predicates      = ["risk_management_standard", "risk_management_absent"],\n    )\n    rule.compiled_check = check_risk_mgmt\n    rules.append(rule)\n\n    # DEV-003: Clinical evidence for Class III\n    def check_clinical(f: FactDict) -> Optional[bool]:\n        device_class    = f.get("device_class")\n        clinical_absent = f.get("clinical_evidence_absent")\n        clinical_n      = f.get("clinical_n")\n\n        if device_class is None:\n            return None   # cannot assess without device class\n        if device_class == "III":\n            if clinical_absent is True:\n                return False\n            if clinical_n is not None and clinical_n < 30:\n                return False\n            if clinical_absent is False or (clinical_n and clinical_n >= 30):\n                return True\n            return None   # uncertain\n        return True   # Class I/II — may not need clinical\n\n    rule = ComplianceRule(\n        rule_id         = "DEV-003",\n        name            = "Clinical evidence adequate for device class",\n        domain          = "fda_device",\n        severity        = "critical",\n        rule_source     = "base",\n        regulation      = "21 CFR 860.7",\n        regulation_text = "Valid scientific evidence is evidence from well-controlled investigations.",\n        regulation_url  = "https://www.ecfr.gov/current/title-21/section-860.7",\n        pass_message    = "Clinical evidence adequate for device classification",\n        fail_message    = "Clinical evidence absent or inadequate for Class III device",\n        predicates      = ["device_class", "clinical_evidence_absent", "clinical_n"],\n    )\n    rule.compiled_check = check_clinical\n    rules.append(rule)\n\n    return rules\n\n\ndef _make_clinical_rules(vocab: PredicateVocabulary) -> List[ComplianceRule]:\n    """Hand-written FDAAA 801 rules for clinical trial compliance."""\n\n    rules = []\n\n    # CLIN-001: Results posting\n    def check_results(f: FactDict) -> Optional[bool]:\n        not_posted = f.get("results_not_posted")\n        posted     = f.get("has_results") or f.get("clinical_results_posted")\n\n        if not_posted is True:\n            return False\n        if posted is True:\n            return True\n        return None\n\n    rule = ComplianceRule(\n        rule_id         = "CLIN-001",\n        name            = "FDAAA 801 results posted within 12 months",\n        domain          = "clinical",\n        severity        = "critical",\n        rule_source     = "base",\n        regulation      = "FDAAA 801 (42 U.S.C. 282(j))",\n        regulation_text = "Responsible parties must submit summary results within 12 months of primary completion.",\n        regulation_url  = "https://www.govinfo.gov/content/pkg/PLAW-110publ85/pdf/PLAW-110publ85.pdf",\n        pass_message    = "Clinical trial results posted within FDAAA 801 timeframe",\n        fail_message    = "Results not posted — FDAAA 801 violation",\n        predicates      = ["results_not_posted", "has_results", "clinical_results_posted"],\n    )\n    rule.compiled_check = check_results\n    rules.append(rule)\n\n    # CLIN-002: Safety termination\n    def check_safety_termination(f: FactDict) -> Optional[bool]:\n        safety = f.get("safety_termination")\n        if safety is True:\n            return False\n        if safety is False:\n            return True\n        return None\n\n    rule = ComplianceRule(\n        rule_id         = "CLIN-002",\n        name            = "Trial not terminated for safety reasons",\n        domain          = "clinical",\n        severity        = "critical",\n        rule_source     = "base",\n        regulation      = "21 CFR 312.44",\n        regulation_text = "FDA may place a clinical hold on an investigation if there is unreasonable risk.",\n        regulation_url  = "https://www.ecfr.gov/current/title-21/section-312.44",\n        pass_message    = "No safety-related termination identified",\n        fail_message    = "Trial terminated due to safety concerns",\n        predicates      = ["safety_termination"],\n    )\n    rule.compiled_check = check_safety_termination\n    rules.append(rule)\n\n    return rules\n\n\ndef _make_sec_rules(vocab: PredicateVocabulary) -> List[ComplianceRule]:\n    """Hand-written SOX/SEC compliance rules."""\n\n    rules = []\n\n    # SEC-001: Material weakness\n    def check_mw(f: FactDict) -> Optional[bool]:\n        mw = f.get("material_weakness_not_disclosed")\n        if mw is True:\n            return False\n        effective = f.get("sox_controls_effective")\n        if effective is True:\n            return True\n        return None\n\n    rule = ComplianceRule(\n        rule_id         = "SEC-001",\n        name            = "No undisclosed material weakness in internal controls",\n        domain          = "sec_financial",\n        severity        = "critical",\n        rule_source     = "base",\n        regulation      = "SOX Section 302/404",\n        regulation_text = "CEO and CFO must certify internal controls effectiveness.",\n        regulation_url  = "https://www.congress.gov/bill/107th-congress/house-bill/3763",\n        pass_message    = "Internal controls effective, no material weakness",\n        fail_message    = "Material weakness present — SOX 302/404 violation",\n        predicates      = ["material_weakness_not_disclosed", "sox_controls_effective"],\n    )\n    rule.compiled_check = check_mw\n    rules.append(rule)\n\n    # SEC-002: No restatement\n    def check_restatement(f: FactDict) -> Optional[bool]:\n        restatement = f.get("financial_restatement")\n        if restatement is True:\n            return False\n        if restatement is False:\n            return True\n        return None\n\n    rule = ComplianceRule(\n        rule_id         = "SEC-002",\n        name            = "No financial restatement required",\n        domain          = "sec_financial",\n        severity        = "critical",\n        rule_source     = "base",\n        regulation      = "SEC Rule 13a-11 / ASC 250",\n        regulation_text = "An entity shall report the correction of a material error.",\n        regulation_url  = "https://www.ecfr.gov/current/title-17/section-240.13a-11",\n        pass_message    = "No financial restatement required",\n        fail_message    = "Financial restatement required — prior statements materially incorrect",\n        predicates      = ["financial_restatement"],\n    )\n    rule.compiled_check = check_restatement\n    rules.append(rule)\n\n    return rules\n\n\ndef build_base_rules(vocab: PredicateVocabulary) -> Dict[str, ComplianceRule]:\n    """Build all base rules and return as rule_id → ComplianceRule dict."""\n    all_rules = []\n    all_rules.extend(_make_gmp_rules(vocab))\n    all_rules.extend(_make_device_rules(vocab))\n    all_rules.extend(_make_clinical_rules(vocab))\n    all_rules.extend(_make_sec_rules(vocab))\n    return {r.rule_id: r for r in all_rules}\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  RULE COMPILER\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass RuleCompiler:\n    """\n    Compiles approved HornClauses into ComplianceRule objects.\n\n    The compiled_check is a pure Python closure:\n      - looks up predicate values from FactDict\n      - returns True (pass), False (fail), or None (uncertain)\n      - zero neural involvement\n\n    Citations come from the predicate vocabulary.\n    No LLM involvement in compilation.\n    """\n\n    def __init__(self, vocab: PredicateVocabulary) -> None:\n        self.vocab = vocab\n\n    def compile(\n        self,\n        clause:      HornClause,\n        approved_by: str,\n        approved_on: str,\n        sme_statement: str,\n    ) -> ComplianceRule:\n        """Compile an approved HornClause to a ComplianceRule."""\n        is_noncompliant = (clause.head == "non_compliant")\n        check_fn = self._make_check(clause.body, is_noncompliant)\n\n        # Derive citations from vocabulary\n        regulations = []\n        reg_texts   = []\n        reg_urls    = []\n        for pred in clause.body:\n            entry = self.vocab.get(pred)\n            if entry:\n                if entry.regulation not in regulations:\n                    regulations.append(entry.regulation)\n                    reg_texts.append(entry.regulation_text)\n                    reg_urls.append(entry.regulation_url)\n\n        regulation      = "; ".join(regulations) if regulations else "See predicate vocabulary"\n        regulation_text = " | ".join(reg_texts[:2]) if reg_texts else ""\n        regulation_url  = reg_urls[0] if reg_urls else ""\n\n        severity = "critical" if clause.confidence >= 0.85 else "major"\n\n        if is_noncompliant:\n            pass_msg = (f"LEARNED-{clause.clause_id}: no violation detected "\n                        f"(conf={clause.confidence:.2f})")\n            fail_msg = (f"LEARNED-{clause.clause_id}: violation pattern detected — "\n                        f"{\', \'.join(clause.body)}")\n        else:\n            pass_msg = (f"LEARNED-{clause.clause_id}: compliance evidence found "\n                        f"(conf={clause.confidence:.2f})")\n            fail_msg = (f"LEARNED-{clause.clause_id}: expected compliance indicators absent — "\n                        f"{\', \'.join(clause.body)}")\n\n        rule = ComplianceRule(\n            rule_id          = f"LEARNED-{clause.clause_id}",\n            name             = clause.notation,\n            domain           = clause.domain,\n            severity         = severity,\n            rule_source      = "learned_ilp",\n            regulation       = regulation,\n            regulation_text  = regulation_text,\n            regulation_url   = regulation_url,\n            pass_message     = pass_msg,\n            fail_message     = fail_msg,\n            predicates       = clause.body,\n            confidence       = clause.confidence,\n            approved_by      = approved_by,\n            approved_on      = approved_on,\n            sme_statement    = sme_statement,\n            training_support = clause.support,\n            horn_notation    = clause.notation,\n        )\n        rule.compiled_check = check_fn\n        return rule\n\n    @staticmethod\n    def _make_check(body: List[str], invert: bool) -> Callable:\n        """\n        Create a compiled check closure for a Horn clause.\n\n        For non_compliant head (invert=True):\n          clause fires when predicates present and True\n          firing means violation → return False (rule fails)\n          not firing means no violation → return True (rule passes)\n\n        For compliant head (invert=False):\n          clause fires when predicates present and True\n          firing means compliance evidence → return True (rule passes)\n          not firing means evidence absent → return None (uncertain)\n        """\n        pred_list = list(body)\n\n        def check(facts: FactDict) -> Optional[bool]:\n            any_uncertain = False\n            fires         = True\n\n            for pred in pred_list:\n                val = facts.get(pred)\n                if val is None:\n                    any_uncertain = True\n                    fires         = False\n                    break\n                if not bool(val):\n                    fires = False\n                    break\n\n            if any_uncertain:\n                return None   # uncertain — NEEDS_REVIEW\n\n            if invert:\n                # non_compliant head: fires → violation → fail\n                return not fires\n            else:\n                # compliant head: fires → evidence found → pass\n                # not fires → evidence absent → uncertain\n                return True if fires else None\n\n        return check\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  SYMBOLIC RULE ENGINE\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass SymbolicRuleEngine:\n    """\n    The sole decision maker in the compliance pipeline.\n\n    Evaluates all applicable rules against a FactDict.\n    Zero neural involvement — pure Python dict lookups.\n\n    Three-valued verdict logic:\n      any critical rule = False → NON_COMPLIANT (confirmed violation)\n      any critical rule = None  → NEEDS_REVIEW  (insufficient evidence)\n      all rules = True          → COMPLIANT\n    """\n\n    def __init__(self, vocab: PredicateVocabulary) -> None:\n        self.vocab   = vocab\n        self._rules: Dict[str, ComplianceRule] = {}\n        self._load_base_rules()\n\n    def _load_base_rules(self) -> None:\n        base = build_base_rules(self.vocab)\n        self._rules.update(base)\n        log.info(f"[Engine] Loaded {len(base)} base rules")\n\n    def add_rule(self, rule: ComplianceRule) -> None:\n        self._rules[rule.rule_id] = rule\n        log.info(f"[Engine] Added rule: {rule.rule_id}")\n\n    def remove_rule(self, rule_id: str) -> None:\n        self._rules.pop(rule_id, None)\n\n    @property\n    def n_rules(self) -> int:\n        return len(self._rules)\n\n    @property\n    def n_base_rules(self) -> int:\n        return sum(1 for r in self._rules.values() if r.rule_source == "base")\n\n    @property\n    def n_learned_rules(self) -> int:\n        return sum(1 for r in self._rules.values() if r.rule_source == "learned_ilp")\n\n    def evaluate(\n        self,\n        facts:  FactDict,\n        domain: str,\n    ) -> Tuple[str, List[RuleResult]]:\n        """\n        Evaluate all applicable rules against facts.\n        Returns (verdict, rule_results).\n        """\n        # Get applicable rules for this domain\n        applicable = [\n            rule for rule in self._rules.values()\n            if rule.domain == domain or rule.domain == "universal"\n        ]\n\n        if not applicable:\n            log.warning(f"[Engine] No rules for domain: {domain}")\n            return "NEEDS_REVIEW", []\n\n        results = [rule.evaluate(facts) for rule in applicable]\n\n        # Three-valued verdict logic — driven by CRITICAL rules only.\n        # Minor/major rule results are informational and surfaced in\n        # rule_results but do not change the verdict by themselves.\n        #\n        # Logic:\n        #   any critical = False  → NON_COMPLIANT  (confirmed violation)\n        #   any critical = None   → NEEDS_REVIEW   (uncertain, escalate)\n        #   all criticals = True  → COMPLIANT      (all requirements met)\n        #\n        # Note: if there are no critical rules for this domain, fall back\n        # to checking all rules so NEEDS_REVIEW is still possible.\n        critical = [r for r in results if r.severity == "critical"]\n\n        if critical:\n            crit_fail    = any(r.passed is False for r in critical)\n            crit_unclear = any(r.passed is None  for r in critical)\n        else:\n            # No critical rules — check all rules\n            crit_fail    = any(r.passed is False for r in results)\n            crit_unclear = any(r.passed is None  for r in results)\n\n        if crit_fail:\n            verdict = "NON_COMPLIANT"\n        elif crit_unclear:\n            verdict = "NEEDS_REVIEW"\n        else:\n            verdict = "COMPLIANT"\n\n        return verdict, results\n\n    def build_verdict(\n        self,\n        facts:          FactDict,\n        domain:         str,\n        doc_hash:       str,\n        system_version: str = "regintel-1.0.0",\n    ) -> Verdict:\n        """Full evaluation returning a Verdict object."""\n        verdict, results = self.evaluate(facts, domain)\n\n        return Verdict(\n            verdict        = verdict,\n            domain         = domain,\n            rule_results   = results,\n            facts          = facts,\n            doc_hash       = doc_hash,\n            timestamp      = datetime.utcnow().isoformat() + "Z",\n            system_version = system_version,\n        )\n\n    def rules_summary(self) -> str:\n        lines = [f"Rules: {self.n_rules} total ({self.n_base_rules} base, "\n                 f"{self.n_learned_rules} learned)"]\n        for rid, rule in sorted(self._rules.items()):\n            src = "BASE   " if rule.rule_source == "base" else "LEARNED"\n            lines.append(f"  [{src}] {rid:<25} {rule.severity:<8} {rule.name[:50]}")\n        return "\\n".join(lines)\n'

_FILES['pipeline.py'] = '"""\nregintel_engine.pipeline\n=========================\nMain RegIntel compliance pipeline.\n\nThe complete neuro-symbolic pipeline:\n\nTEST TIME (every document):\n  Document text\n      ↓ LLM extraction (only AI at test time)\n  ExtractedFacts\n      ↓ Hallucination verification\n  Verified facts\n      ↓ Normalization + text classification\n  FactDict (discrete only — no embeddings)\n      ↓ Symbolic rule engine (zero AI)\n  Verdict\n      ↓ Audit chain (HMAC signed)\n  AuditRecord\n\nTRAINING TIME (once, offline):\n  Labeled documents\n      ↓ LLM extraction (same pipeline)\n  (facts, label) pairs\n      ↓ Domain-constrained ILP\n  HornClauses\n      ↓ DreamCoder abstraction\n  Primitives + refined clauses\n      ↓ SME review (human approves)\n  Approved clauses\n      ↓ Rule compiler\n  ComplianceRules → symbolic engine\n\nUsage\n-----\n    pipeline = RegIntelPipeline.create()\n\n    # Test time\n    result = pipeline.run(document_text, domain="gmp")\n    print(result.verdict.verdict)\n\n    # Training time\n    pipeline.training.train(labeled_examples)\n    pipeline.training.approve_clause(clause, "sme@company.com", ...)\n"""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport logging\nimport re\nfrom dataclasses import dataclass\nfrom datetime import datetime\nfrom typing import Any, Dict, List, Optional\n\nfrom .models import (\n    ExtractedFact, FactDict, HornClause, Verdict, AuditRecord,\n)\nfrom .vocabulary import PredicateVocabulary, EncodingTables\nfrom .extraction.llm_extractor import LLMFactExtractor\nfrom .extraction.verifier import (\n    HallucinationVerifier, FactNormalizer, FactDictBuilder,\n)\nfrom .rules.engine import SymbolicRuleEngine, RuleCompiler\nfrom .audit.chain import HMACauditChain\nfrom .ilp.sparse_ilp import SparseILP, DreamCoder, ILPConfig\n\nlog = logging.getLogger("regintel.pipeline")\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  PIPELINE RESULT\n# ─────────────────────────────────────────────────────────────────────────────\n\n@dataclass\nclass PipelineResult:\n    """Complete output from one document evaluation."""\n    verdict:      Verdict\n    audit_record: AuditRecord\n    facts:        FactDict\n\n    @property\n    def label(self) -> str:\n        return self.verdict.verdict\n\n    @property\n    def is_compliant(self) -> bool:\n        return self.label == "COMPLIANT"\n\n    def explain(self) -> str:\n        """Human-readable explanation of the verdict."""\n        lines = [\n            f"Verdict: {self.verdict.verdict}",\n            f"Domain:  {self.verdict.domain}",\n            "",\n        ]\n\n        failed = self.verdict.failed_rules\n        if failed:\n            lines.append("FINDINGS:")\n            for r in failed:\n                lines.append(f"  [{r.severity.upper()}] {r.rule_id}: {r.message}")\n                for pred, ev in r.evidence.items():\n                    if ev.get("value") is not None:\n                        lines.append(\n                            f"    {pred} = {ev[\'value\']}"\n                            f" ← \\"{ev.get(\'extracted_text\', \'\')[:80]}\\""\n                        )\n            lines.append("")\n\n        uncertain = self.verdict.uncertain_rules\n        if uncertain:\n            lines.append("UNCERTAIN (insufficient evidence):")\n            for r in uncertain:\n                lines.append(f"  [{r.severity.upper()}] {r.rule_id}: {r.message}")\n            lines.append("")\n\n        passed = [r for r in self.verdict.rule_results if r.passed is True]\n        if passed:\n            lines.append(f"PASSED: {len(passed)} rules")\n\n        return "\\n".join(lines)\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  TRAINING ORCHESTRATOR\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass TrainingOrchestrator:\n    """\n    Orchestrates the training-time pipeline.\n\n    Runs ILP on extracted facts, manages DreamCoder abstraction,\n    handles SME approval workflow, compiles approved rules.\n    """\n\n    def __init__(\n        self,\n        vocab:    PredicateVocabulary,\n        engine:   SymbolicRuleEngine,\n        ilp:      SparseILP,\n        compiler: RuleCompiler,\n        dreamcoder: DreamCoder,\n    ) -> None:\n        self.vocab      = vocab\n        self.engine     = engine\n        self.ilp        = ilp\n        self.compiler   = compiler\n        self.dreamcoder = dreamcoder\n        self._pending:  List[HornClause] = []\n\n    def train(\n        self,\n        examples:           List[Dict[str, Any]],\n        run_dreamcoder:     bool = True,\n    ) -> List[HornClause]:\n        """\n        Run ILP on labeled examples to discover rules.\n\n        Parameters\n        ----------\n        examples     List of {"facts": sparse_dict, "label": "COMPLIANT"|"NON_COMPLIANT",\n                              "domain": "gmp"|"fda_device"|"clinical"|"sec_financial"}\n        run_dreamcoder  Whether to run DreamCoder abstraction after ILP\n\n        Returns\n        -------\n        Discovered HornClauses (pending SME approval)\n        """\n        # Group examples by domain\n        by_domain: Dict[str, List[Dict]] = {}\n        for ex in examples:\n            domain = ex.get("domain", "gmp")\n            by_domain.setdefault(domain, []).append(ex)\n\n        all_clauses = []\n        for domain, domain_examples in by_domain.items():\n            log.info(f"[Training] ILP for domain={domain} "\n                     f"n={len(domain_examples)}")\n            clauses = self.ilp.induce(domain_examples, domain)\n            all_clauses.extend(clauses)\n            log.info(f"[Training] domain={domain}: "\n                     f"{len(clauses)} clauses discovered")\n\n        if run_dreamcoder and all_clauses:\n            new_primitives = self.dreamcoder.wake(all_clauses)\n            if new_primitives:\n                all_clauses = self.dreamcoder.sleep(all_clauses)\n                log.info(f"[DreamCoder] {len(new_primitives)} primitives, "\n                         f"{len(all_clauses)} compressed clauses")\n\n        self._pending.extend(all_clauses)\n\n        log.info(f"[Training] Complete: {len(all_clauses)} total clauses "\n                 f"({len(self._pending)} pending approval)")\n        return all_clauses\n\n    def pending_clauses(self) -> List[HornClause]:\n        """Return clauses awaiting SME review."""\n        return [c for c in self._pending if c.status == "pending"]\n\n    def approve_clause(\n        self,\n        clause_id:    str,\n        approved_by:  str,\n        sme_statement: str,\n        regulation:   Optional[str] = None,\n    ) -> bool:\n        """\n        SME approves a discovered clause.\n        Compiles it to a ComplianceRule and adds to the engine.\n        """\n        clause = next((c for c in self._pending if c.clause_id == clause_id), None)\n        if not clause:\n            log.warning(f"[Training] Clause not found: {clause_id}")\n            return False\n\n        if not clause.is_approvable:\n            log.warning(f"[Training] Clause {clause_id} not approvable: "\n                        f"conf={clause.confidence:.2f}, "\n                        f"body={clause.body}")\n            return False\n\n        clause.status = "approved"\n\n        approved_on = datetime.utcnow().strftime("%Y-%m-%d")\n\n        rule = self.compiler.compile(\n            clause        = clause,\n            approved_by   = approved_by,\n            approved_on   = approved_on,\n            sme_statement = sme_statement,\n        )\n\n        self.engine.add_rule(rule)\n        log.info(f"[Training] Approved and compiled: {rule.rule_id}")\n        return True\n\n    def reject_clause(self, clause_id: str, reason: str) -> None:\n        clause = next((c for c in self._pending if c.clause_id == clause_id), None)\n        if clause:\n            clause.status = "rejected"\n            log.info(f"[Training] Rejected clause {clause_id}: {reason}")\n\n    def sme_review_summary(self) -> str:\n        """Print summary for SME review."""\n        pending = self.pending_clauses()\n        if not pending:\n            return "No clauses pending review."\n\n        lines = [\n            f"{\'=\'*70}",\n            f"SME REVIEW REQUIRED — {len(pending)} clauses pending",\n            f"{\'=\'*70}",\n        ]\n        for c in pending:\n            approvable = "✓ APPROVABLE" if c.is_approvable else "✗ NOT APPROVABLE"\n            lines.append(f"\\n[{c.clause_id}] {approvable}")\n            lines.append(f"  Notation:   {c.notation}")\n            lines.append(f"  Domain:     {c.domain}")\n            lines.append(f"  Confidence: {c.confidence:.2f}")\n            lines.append(f"  Coverage:   {c.coverage:.2f}")\n            lines.append(f"  Support:    {c.support} training docs")\n            lines.append(f"  Predicates: {\', \'.join(c.body)}")\n\n            # Show citations from vocabulary\n            for pred in c.body:\n                entry = self.vocab.get(pred)\n                if entry:\n                    lines.append(f"  Citation [{pred}]: {entry.regulation}")\n\n        lines.append(f"\\n{\'=\'*70}")\n        return "\\n".join(lines)\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n#  MAIN PIPELINE\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass RegIntelPipeline:\n    """\n    The complete RegIntel neuro-symbolic compliance pipeline.\n\n    At test time:\n      1. LLM extracts facts (only AI — runs locally, no external calls)\n      2. Verifier checks grounding (no AI — string operations)\n      3. Normalizer maps to standard vocabulary (no AI)\n      4. FactDictBuilder creates discrete FactDict (no AI)\n      5. SymbolicRuleEngine evaluates rules (no AI — Python functions)\n      6. AuditChain seals HMAC record (no AI)\n\n    At training time:\n      1. Same extraction pipeline on labeled documents\n      2. ILP discovers rules from (facts, label) pairs\n      3. DreamCoder abstracts patterns to primitives\n      4. SME reviews and approves clauses\n      5. RuleCompiler creates compiled Python functions\n      6. Engine updated with new rules\n    """\n\n    def __init__(\n        self,\n        extractor:  LLMFactExtractor,\n        verifier:   HallucinationVerifier,\n        normalizer: FactNormalizer,\n        builder:    FactDictBuilder,\n        engine:     SymbolicRuleEngine,\n        audit:      HMACauditChain,\n        vocab:      PredicateVocabulary,\n        training:   TrainingOrchestrator,\n    ) -> None:\n        self.extractor  = extractor\n        self.verifier   = verifier\n        self.normalizer = normalizer\n        self.builder    = builder\n        self.engine     = engine\n        self.audit      = audit\n        self.vocab      = vocab\n        self.training   = training\n\n    @classmethod\n    def create(\n        cls,\n        llm_model:  str  = "Qwen/Qwen2.5-1.5B-Instruct",\n        mock_llm:   bool = False,\n        audit_key:  Optional[str] = None,\n        ilp_config: Optional[ILPConfig] = None,\n    ) -> "RegIntelPipeline":\n        """\n        Create a complete pipeline.\n\n        Parameters\n        ----------\n        llm_model   HuggingFace model name for LLM extractor\n        mock_llm    Use mock LLM (no model needed — for testing)\n        audit_key   HMAC key hex string (or set REGINTEL_AUDIT_KEY env var)\n        ilp_config  ILP hyperparameters\n        """\n        vocab      = PredicateVocabulary.default()\n        encoding   = EncodingTables()\n\n        extractor  = (LLMFactExtractor.mock() if mock_llm\n                      else LLMFactExtractor.from_model(llm_model))\n        verifier   = HallucinationVerifier()\n        normalizer = FactNormalizer()\n\n        # Pass all vocabulary predicate names so ILP dict is filtered to\n        # controlled vocabulary only — no spurious noise facts\n        all_vocab_names = set(vocab.get_names())   # universal + all domains\n        builder    = FactDictBuilder(encoding, vocab_names=all_vocab_names)\n        engine     = SymbolicRuleEngine(vocab)\n\n        audit      = HMACauditChain(key_hex=audit_key)\n        ilp        = SparseILP(vocab, ilp_config or ILPConfig())\n        compiler   = RuleCompiler(vocab)\n        dreamcoder = DreamCoder()\n\n        training   = TrainingOrchestrator(\n            vocab=vocab, engine=engine, ilp=ilp,\n            compiler=compiler, dreamcoder=dreamcoder,\n        )\n\n        log.info(f"[Pipeline] Created: {engine.n_rules} base rules, "\n                 f"LLM={\'mock\' if mock_llm else llm_model}")\n\n        return cls(\n            extractor  = extractor,\n            verifier   = verifier,\n            normalizer = normalizer,\n            builder    = builder,\n            engine     = engine,\n            audit      = audit,\n            vocab      = vocab,\n            training   = training,\n        )\n\n    def run(\n        self,\n        document: str,\n        domain:   str = "gmp",\n    ) -> PipelineResult:\n        """\n        Run the complete pipeline on one document.\n\n        STAGE 1 — LLM extraction (only AI)\n        STAGE 2 — Verification + normalization (no AI)\n        STAGE 3 — Symbolic evaluation (no AI)\n        STAGE 4 — Audit sealing (no AI)\n        """\n        doc_hash = hashlib.sha256(document.encode()).hexdigest()\n\n        # ── Stage 1: LLM extracts facts ───────────────────────────────────────\n        structured_raw = self.extractor.extract_structured(document, domain)\n\n        # Classify text facts (deviation descriptions, summaries, etc.)\n        text_preds = []\n        vocab_str  = self.vocab.get_classification_prompt_vocab(domain)\n        known_text_fields = [\n            "deviation_description", "violation_description",\n            "reason_for_recall", "clinical_summary",\n            "why_stopped", "audit_findings",\n        ]\n        for field in known_text_fields:\n            # Look for this field in the document\n            field_text = self._extract_field_text(document, field)\n            if field_text:\n                preds = self.extractor.classify_text(\n                    text         = field_text,\n                    field_name   = field,\n                    vocabulary   = vocab_str,\n                    domain       = domain,\n                )\n                text_preds.extend(preds)\n\n        # ── Stage 2: Verify + normalize + build FactDict ──────────────────────\n        verified_struct, _ = self.verifier.verify(structured_raw, document)\n        verified_text,  _ = self.verifier.verify(text_preds, document)\n\n        verified_struct = self.normalizer.normalize_all(verified_struct)\n        verified_text   = self.normalizer.normalize_all(verified_text)\n\n        fact_dict = self.builder.build(\n            structured_facts     = verified_struct,\n            text_predicate_facts = verified_text,\n            domain               = domain,\n        )\n\n        # ── Stage 3: Symbolic rule engine ─────────────────────────────────────\n        verdict = self.engine.build_verdict(fact_dict, domain, doc_hash)\n\n        # ── Stage 4: Seal audit record ────────────────────────────────────────\n        audit_record = self.audit.seal(verdict)\n\n        return PipelineResult(\n            verdict      = verdict,\n            audit_record = audit_record,\n            facts        = fact_dict,\n        )\n\n    def prepare_training_example(\n        self,\n        document: str,\n        label:    str,\n        domain:   str,\n    ) -> Optional[Dict[str, Any]]:\n        """\n        Prepare one labeled document for ILP training.\n        Returns sparse facts dict ready for SparseILP.induce().\n        """\n        # Run extraction + verification\n        structured_raw = self.extractor.extract_structured(document, domain)\n        verified, _    = self.verifier.verify(structured_raw, document)\n        verified       = self.normalizer.normalize_all(verified)\n\n        vocab_str   = self.vocab.get_classification_prompt_vocab(domain)\n        text_preds  = []\n        for field in ["deviation_description", "reason_for_recall",\n                      "violation_description", "why_stopped"]:\n            text = self._extract_field_text(document, field)\n            if text:\n                preds = self.extractor.classify_text(\n                    text=text, field_name=field,\n                    vocabulary=vocab_str, domain=domain)\n                verified_preds, _ = self.verifier.verify(preds, document)\n                text_preds.extend(verified_preds)\n\n        verified = self.normalizer.normalize_all(verified)\n        text_preds = self.normalizer.normalize_all(text_preds)\n\n        fact_dict = self.builder.build(verified, text_preds, domain)\n        sparse    = self.builder.build_ilp_sparse_dict(fact_dict)\n\n        if not sparse:\n            return None\n\n        return {\n            "facts":  sparse,\n            "label":  label,\n            "domain": domain,\n        }\n\n    def prepare_training_batch(\n        self,\n        documents: List[Dict[str, Any]],\n    ) -> List[Dict[str, Any]]:\n        """\n        Prepare a batch of labeled documents for ILP training.\n        documents: List of {"document": str, "label": str, "domain": str}\n        """\n        examples = []\n        for i, doc in enumerate(documents):\n            ex = self.prepare_training_example(\n                doc["document"], doc["label"], doc.get("domain", "gmp"))\n            if ex:\n                examples.append(ex)\n            if (i + 1) % 50 == 0:\n                log.info(f"[Training prep] {i+1}/{len(documents)} documents processed")\n\n        log.info(f"[Training prep] {len(examples)}/{len(documents)} "\n                 f"examples ready for ILP")\n        return examples\n\n    # ── Domain-aware field extraction patterns ────────────────────────────────\n    # Maps logical field names to regex patterns that match the actual section\n    # headers found in real FDA/SEC/ClinicalTrials documents.\n    # Each pattern captures the text following the header.\n\n    _FIELD_PATTERNS: Dict[str, List[str]] = {\n        # FDA drug/device enforcement records\n        "reason_for_recall": [\n            r"REASON FOR RECALL[^:\\n]*[:\\n]\\s*",\n            r"REASON FOR VIOLATION[^:\\n]*[:\\n]\\s*",\n            r"Reason for Recall[^:\\n]*[:\\n]\\s*",\n        ],\n        "violation_description": [\n            r"VIOLATION DESCRIPTION[^:\\n]*[:\\n]\\s*",\n            r"VIOLATION[^:\\n]*[:\\n]\\s*",\n            r"FINDINGS?[^:\\n]*[:\\n]\\s*",\n            r"OBSERVATION[^:\\n]*[:\\n]\\s*",\n        ],\n        "deviation_description": [\n            r"DEVIATION[^:\\n]*[:\\n]\\s*",\n            r"DISCREPANCY[^:\\n]*[:\\n]\\s*",\n            r"OUT.OF.SPECIFICATION[^:\\n]*[:\\n]\\s*",\n            r"OOS INVESTIGATION[^:\\n]*[:\\n]\\s*",\n        ],\n        # Clinical trial records\n        "why_stopped": [\n            r"Reason Stopped[^:\\n]*[:\\n]\\s*",\n            r"WHY STOPPED[^:\\n]*[:\\n]\\s*",\n            r"Why the Study Was Stopped[^:\\n]*[:\\n]\\s*",\n            r"REASON FOR TERMINATION[^:\\n]*[:\\n]\\s*",\n        ],\n        "clinical_summary": [\n            r"BRIEF SUMMARY[^:\\n]*[:\\n]\\s*",\n            r"Brief Summary[^:\\n]*[:\\n]\\s*",\n            r"STUDY OVERVIEW[^:\\n]*[:\\n]\\s*",\n        ],\n        "primary_outcome": [\n            r"PRIMARY OUTCOME[^:\\n]*[:\\n]\\s*",\n            r"Primary Outcome[^:\\n]*[:\\n]\\s*",\n            r"PRIMARY ENDPOINT[^:\\n]*[:\\n]\\s*",\n        ],\n        # SEC filings\n        "audit_findings": [\n            r"MATERIAL WEAKNESS[^:\\n]*[:\\n]\\s*",\n            r"Material Weakness[^:\\n]*[:\\n]\\s*",\n            r"INTERNAL CONTROL[^:\\n]*[:\\n]\\s*",\n            r"MANAGEMENT.S ASSESSMENT[^:\\n]*[:\\n]\\s*",\n        ],\n        # Generic fallback — field name as header (last resort)\n        "_generic": [\n            r"{field}[^:\\n]*[:\\n]\\s*",\n        ],\n    }\n\n    def _extract_field_text(\n        self,\n        document: str,\n        field:    str,\n    ) -> Optional[str]:\n        """\n        Extract text for a specific semantic field from a document.\n\n        Uses domain-aware regex patterns that match real document headers\n        (e.g. "REASON FOR RECALL / VIOLATION DESCRIPTION:", "Reason Stopped:").\n        Falls back to generic field-name matching.\n\n        Returns up to 600 chars of the section text, or None if not found.\n        """\n        patterns = self._FIELD_PATTERNS.get(field, [])\n\n        # Always try the generic fallback last\n        generic_pattern = field.replace("_", r"[\\s_]")\n        patterns = patterns + [rf"(?i){generic_pattern}[^:\\n]*[:\\n]\\s*"]\n\n        for pattern in patterns:\n            try:\n                match = re.search(pattern, document, re.IGNORECASE)\n                if match:\n                    start = match.end()\n                    # Extract up to next all-caps section header or 600 chars\n                    remainder = document[start:start + 800]\n                    # Stop at next section header (all caps line or labelled field)\n                    stop = re.search(\n                        r"\\n[A-Z][A-Z\\s/]{5,}[:\\n]", remainder)\n                    if stop:\n                        text = remainder[:stop.start()].strip()\n                    else:\n                        text = remainder[:600].strip()\n                    if text and len(text) >= 15:\n                        return text\n            except re.error:\n                continue\n\n        return None\n\n    def rules_summary(self) -> str:\n        return self.engine.rules_summary()\n\n    # ── Rule persistence ──────────────────────────────────────────────────────\n\n    def save_rules(self, path: str) -> None:\n        """\n        Save all ILP-discovered (learned) rules to disk.\n        Allows ILP training results to persist between Kaggle sessions.\n\n        Saves: clause notation, predicates, domain, confidence, provenance.\n        Does NOT save compiled_check (regenerated on load from the clause data).\n        """\n        import json, os\n        from dataclasses import asdict\n\n        learned = [\n            r for r in self.engine._rules.values()\n            if r.rule_source == "learned_ilp"\n        ]\n        records = []\n        for rule in learned:\n            records.append({\n                "rule_id":         rule.rule_id,\n                "name":            rule.name,\n                "domain":          rule.domain,\n                "severity":        rule.severity,\n                "regulation":      rule.regulation,\n                "regulation_text": rule.regulation_text,\n                "regulation_url":  rule.regulation_url,\n                "pass_message":    rule.pass_message,\n                "fail_message":    rule.fail_message,\n                "predicates":      rule.predicates,\n                "confidence":      rule.confidence,\n                "approved_by":     rule.approved_by,\n                "approved_on":     rule.approved_on,\n                "sme_statement":   rule.sme_statement,\n                "training_support":rule.training_support,\n                "horn_notation":   rule.horn_notation,\n            })\n\n        os.makedirs(os.path.dirname(path) if os.path.dirname(path) else ".", exist_ok=True)\n        with open(path, "w") as f:\n            json.dump(records, f, indent=2)\n\n        log.info(f"[Pipeline] Saved {len(records)} learned rules → {path}")\n\n    def load_rules(self, path: str) -> int:\n        """\n        Load previously saved ILP rules back into the engine.\n        Recompiles compiled_check from the saved predicate list.\n        Returns number of rules loaded.\n        """\n        import json\n        from .models import ComplianceRule\n        from .rules.engine import RuleCompiler\n\n        if not __import__("os").path.exists(path):\n            log.warning(f"[Pipeline] Rules file not found: {path}")\n            return 0\n\n        with open(path) as f:\n            records = json.load(f)\n\n        compiler = RuleCompiler(self.vocab)\n        n_loaded = 0\n\n        for rec in records:\n            # Reconstruct HornClause-like data to recompile check function\n            from .models import HornClause\n            predicates = rec["predicates"]\n            head = "non_compliant" if "non_compliant" in rec["name"] else "compliant"\n\n            is_noncompliant = (head == "non_compliant")\n            check_fn = RuleCompiler._make_check(predicates, is_noncompliant)\n\n            rule = ComplianceRule(\n                rule_id         = rec["rule_id"],\n                name            = rec["name"],\n                domain          = rec["domain"],\n                severity        = rec["severity"],\n                rule_source     = "learned_ilp",\n                regulation      = rec["regulation"],\n                regulation_text = rec["regulation_text"],\n                regulation_url  = rec["regulation_url"],\n                pass_message    = rec["pass_message"],\n                fail_message    = rec["fail_message"],\n                predicates      = predicates,\n                confidence      = rec["confidence"],\n                approved_by     = rec.get("approved_by", ""),\n                approved_on     = rec.get("approved_on", ""),\n                sme_statement   = rec.get("sme_statement", ""),\n                training_support= rec.get("training_support", 0),\n                horn_notation   = rec.get("horn_notation", ""),\n            )\n            rule.compiled_check = check_fn\n            self.engine.add_rule(rule)\n            n_loaded += 1\n\n        log.info(f"[Pipeline] Loaded {n_loaded} learned rules from {path}")\n        return n_loaded\n'

_FILES['__init__.py'] = '"""RegIntel Neuro-Symbolic Compliance Engine v1.0"""\n__version__ = "1.0.0"\n\nfrom .pipeline import RegIntelPipeline, PipelineResult\nfrom .models import (\n    ExtractedFact, FactDict, RuleResult, Verdict,\n    ComplianceRule, HornClause, AuditRecord,\n)\nfrom .vocabulary import PredicateVocabulary, EncodingTables\n\n__all__ = [\n    "RegIntelPipeline", "PipelineResult",\n    "ExtractedFact", "FactDict", "RuleResult", "Verdict",\n    "ComplianceRule", "HornClause", "AuditRecord",\n    "PredicateVocabulary", "EncodingTables",\n]\n'


