import os

# Set mock_llm=False if GPU is available and you want real LLM extraction
MOCK_LLM  = True   # Set False for Qwen2.5-1.5B on GPU
AUDIT_KEY = os.environ.get('REGINTEL_AUDIT_KEY', 'a' * 64)

ilp_config = ILPConfig(
    n_epochs         = 300,
    learning_rate    = 0.05,
    l1_lambda        = 0.01,
    top_k_predicates = 3,
    min_confidence   = 0.75,
    min_coverage     = 0.10,
    min_support      = 5,
    score_scale      = 1.5,
)

pipeline = RegIntelPipeline.create(
    mock_llm   = MOCK_LLM,
    audit_key  = AUDIT_KEY,
    ilp_config = ilp_config,
)

print(f"Pipeline created:")
print(f"  Base rules:    {pipeline.engine.n_base_rules}")
print(f"  Vocabulary:    {len(pipeline.vocab.get_names())} predicates across 4 domains")
print(f"  LLM mode:      {'mock (fast, no GPU)' if MOCK_LLM else 'Qwen2.5-1.5B (GPU)'}")
print()
print(pipeline.engine.rules_summary())


