import time

print("Preparing training examples for ILP...")
print("(With mock LLM: ~10-30s | With Qwen GPU: ~5-10 min)")
t0 = time.time()

ilp_examples = pipeline.prepare_training_batch(train_docs)

elapsed = time.time() - t0
print(f"\nPreparation complete ({elapsed:.1f}s):")
print(f"  {len(ilp_examples)}/{len(train_docs)} documents → sparse facts")

# Show predicate coverage
pred_counts: Counter = Counter()
domain_pred_counts = {}
for ex in ilp_examples:
    d = ex.get('domain', 'unknown')
    domain_pred_counts.setdefault(d, Counter())
    for pred in ex['facts']:
        pred_counts[pred] += 1
        domain_pred_counts[d][pred] += 1

print(f"\nTop predicates in training set:")
for pred, count in pred_counts.most_common(15):
    pct = count / max(len(ilp_examples), 1)
    bar = '█' * int(pct * 25)
    print(f"  {pred:<42} {bar} {count} ({pct:.0%})")

print(f"\nPredicates by domain:")
for domain, counts in sorted(domain_pred_counts.items()):
    top = [p for p, _ in counts.most_common(3)]
    print(f"  {domain:<22} → {', '.join(top)}")


