# Check if previously saved rules exist — skip retraining if so
RULES_PATH = "/kaggle/working/ilp_rules.json"

if os.path.exists(RULES_PATH):
    print(f"Loading saved ILP rules from {RULES_PATH}...")
    n = pipeline.load_rules(RULES_PATH)
    print(f"Loaded {n} rules. Skipping ILP training.")
else:
    print("Running ILP on labeled training examples...")
    t0 = time.time()

    discovered_clauses = pipeline.training.train(
        ilp_examples,
        run_dreamcoder = True,
    )

    elapsed = time.time() - t0
    pending = pipeline.training.pending_clauses()

    print(f"\nILP Training complete ({elapsed:.1f}s):")
    print(f"  Discovered: {len(discovered_clauses)} clauses")
    print(f"  Pending SME review: {len(pending)} clauses")

    if discovered_clauses:
        print("\nDiscovered clauses:")
        for c in discovered_clauses:
            flag = "✓ APPROVABLE" if c.is_approvable else "— below threshold"
            print(f"  [{flag}] {c.notation}")
            print(f"    conf={c.confidence:.2f}  coverage={c.coverage:.2f}  "
                  f"support={c.support}  domain={c.domain}")

    # Auto-approve for evaluation
    # PRODUCTION: replace with real SME review using sme_review_summary()
    n_approved = 0
    for clause in pending:
        if clause.is_approvable:
            ok = pipeline.training.approve_clause(
                clause.clause_id,
                approved_by    = "auto_eval@regintel.ai",
                sme_statement  = (
                    f"Auto-approved for evaluation run. "
                    f"REQUIRES human SME review before production deployment. "
                    f"conf={clause.confidence:.2f} support={clause.support}"
                ),
            )
            if ok:
                n_approved += 1

    print(f"\n  {n_approved} clauses auto-approved for evaluation")
    print(f"  Engine: {pipeline.engine.n_base_rules} base + {pipeline.engine.n_learned_rules} learned rules")

    # Save rules for future sessions
    pipeline.save_rules(RULES_PATH)
    print(f"\nRules saved to {RULES_PATH} (reload next session with pipeline.load_rules())")


