from typing import Dict, List, Any

def evaluate(pipeline, test_docs, verbose=True):
    results = []
    t0 = time.time()

    for i, doc in enumerate(test_docs):
        try:
            result = pipeline.run(doc['document'], domain=doc['domain'])
            pred   = result.verdict.verdict
        except Exception as e:
            pred = 'ERROR'

        results.append({
            'domain':     doc['domain'],
            'true_label': doc['label'],
            'pred_label': pred,
            'correct':    pred == doc['label'],
        })

        if verbose and (i + 1) % 25 == 0:
            print(f"  {i+1}/{len(test_docs)}  ({time.time()-t0:.0f}s)")

    def metrics(subset, pos='NON_COMPLIANT'):
        tp = sum(1 for r in subset if r['true_label']==pos and r['pred_label']==pos)
        fp = sum(1 for r in subset if r['true_label']!=pos and r['pred_label']==pos)
        fn = sum(1 for r in subset if r['true_label']==pos and r['pred_label']!=pos)
        tn = sum(1 for r in subset if r['true_label']!=pos and r['pred_label']!=pos)
        nr = sum(1 for r in subset if r['pred_label']=='NEEDS_REVIEW')
        n  = len(subset)
        prec = tp / max(tp+fp, 1)
        rec  = tp / max(tp+fn, 1)
        f1   = 2*prec*rec / max(prec+rec, 1e-10)
        acc  = (tp+tn) / max(n-nr, 1)
        return dict(tp=tp, fp=fp, fn=fn, tn=tn, nr=nr, n=n,
                    precision=round(prec,3), recall=round(rec,3),
                    f1=round(f1,3), accuracy=round(acc,3),
                    nr_rate=round(nr/max(n,1),3))

    overall    = metrics(results)
    per_domain = {d: metrics([r for r in results if r['domain']==d])
                  for d in sorted({r['domain'] for r in results})}

    return dict(overall=overall, per_domain=per_domain,
                results=results, elapsed_s=round(time.time()-t0, 1))


print("Evaluating on test set...")
ev = evaluate(pipeline, test_docs)
print(f"Complete ({ev['elapsed_s']}s)")


