def to_pipeline_format(doc):
    return {
        "document":       doc.get('document', ''),
        "label":          doc.get('label', ''),
        "domain":         doc.get('domain', ''),
        "doc_id":         doc.get('doc_id', ''),
        "cfr_sections":   doc.get('cfr_sections', []),
        "violation_type": doc.get('violation_type'),
        "ground_truth_violations": doc.get('ground_truth_violations', []),
        "label_confidence": doc.get('label_confidence', 'high'),
    }

for split_name, split_docs in [("train", train_docs), ("test", test_docs)]:
    out_docs = [to_pipeline_format(d) for d in split_docs]
    out_path = f"/kaggle/working/{split_name}_for_pipeline.json"
    with open(out_path, "w") as f:
        json.dump(out_docs, f)
    print(f"{out_path}  {len(out_docs):,} docs")

